/**
 * logger.js
 * ==========
 * Structured logging for the AD ↔ Cognito sync service.
 *
 * AWS Lambda automatically pipes console.log/warn/error output to
 * CloudWatch Logs. This module wraps console methods with:
 *
 *   • Three log levels:  ERROR | NORMAL | DEBUG
 *   • Structured JSON output for machine parsing in CloudWatch Insights
 *   • Consistent prefixes for filtering ([AD], [Cognito], [Sync], etc.)
 *   • Timing utilities for performance measurement
 *
 * LOG LEVELS:
 * ───────────────────────────────────────────────────────────────────
 *   ERROR  — Only errors and conflicts are logged. Use this in production
 *            when the sync is stable and you only want to know about failures.
 *
 *   NORMAL — High-level connection events, batch summaries, and all errors.
 *            This is the recommended production default. You'll see:
 *              • Connection/authentication success/failure
 *              • Batch start/end with user counts
 *              • Sync summary statistics
 *              • All errors and conflicts
 *              • Delta sync skip counts
 *
 *   DEBUG  — Everything. Every user processed, every API call, every
 *            attribute comparison. Use only for troubleshooting — this
 *            generates significant CloudWatch log volume (and cost).
 *
 * CONFIGURATION:
 *   Set the LOG_LEVEL environment variable:
 *     LOG_LEVEL=ERROR | NORMAL | DEBUG
 *   Default: NORMAL
 *
 * CLOUDWATCH INSIGHTS QUERIES:
 *   To find all errors:
 *     filter level = "ERROR"
 *
 *   To find sync summaries:
 *     filter level = "NORMAL" and component = "Sync"
 *
 *   To trace a specific user:
 *     filter level = "DEBUG" and message like /alice@example.com/
 *
 *   To find delta-skipped users:
 *     filter event = "DELTA_SKIP"
 */

"use strict";

// ─────────────────────────────────────────────────────────────────────────────
// Log level constants and configuration
// ─────────────────────────────────────────────────────────────────────────────

const LOG_LEVELS = {
  ERROR: 0,   // Only errors and conflicts
  NORMAL: 1,  // Connections, summaries, errors
  DEBUG: 2,   // Everything
};

/** Current log level — read from environment, default NORMAL */
const CURRENT_LEVEL = LOG_LEVELS[
  (process.env.LOG_LEVEL || "NORMAL").toUpperCase()
] ?? LOG_LEVELS.NORMAL;

// ─────────────────────────────────────────────────────────────────────────────
// Core logging functions
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Write a structured log entry to CloudWatch.
 *
 * Every log entry is a JSON object with these fields:
 *   - timestamp:  ISO 8601 timestamp
 *   - level:      ERROR | NORMAL | DEBUG
 *   - component:  Source module (AD, Cognito, Sync, State, Lambda, Delta)
 *   - event:      Machine-readable event name (e.g. USER_CREATED, BATCH_START)
 *   - message:    Human-readable description
 *   - data:       Optional structured data payload
 *   - syncId:     Current sync run ID (if set)
 *   - batch:      Current batch identifier (if set)
 *
 * @param {"ERROR"|"NORMAL"|"DEBUG"} level
 * @param {string} component  - Module tag (AD, Cognito, Sync, State, Lambda, Delta)
 * @param {string} event      - Machine-readable event code
 * @param {string} message    - Human-readable message
 * @param {Object} [data]     - Optional structured payload
 */
function log(level, component, event, message, data) {
  const numericLevel = LOG_LEVELS[level] ?? LOG_LEVELS.DEBUG;

  // Skip if below current log level
  if (numericLevel > CURRENT_LEVEL) return;

  const entry = {
    timestamp: new Date().toISOString(),
    level,
    component,
    event,
    message,
    ...(data !== undefined && data !== null ? { data } : {}),
    ...(logger._tenantId ? { tenantId: logger._tenantId } : {}),
    ...(logger._syncId ? { syncId: logger._syncId } : {}),
    ...(logger._batch ? { batch: logger._batch } : {}),
  };

  // Route to appropriate console method for CloudWatch severity
  if (level === "ERROR") {
    console.error(JSON.stringify(entry));
  } else if (level === "NORMAL") {
    console.log(JSON.stringify(entry));
  } else {
    // DEBUG — use console.log but CloudWatch will still capture it
    console.log(JSON.stringify(entry));
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Public Logger API
// ─────────────────────────────────────────────────────────────────────────────

const logger = {
  /** Internal state for contextual logging */
  _syncId: null,
  _batch: null,
  _tenantId: null,

  /**
   * Set the tenant ID for inclusion in all log entries (multi-tenant mode).
   * @param {string} tenantId
   */
  setTenantId(tenantId) {
    this._tenantId = tenantId;
  },

  /**
   * Set the current sync run ID for inclusion in all log entries.
   * @param {string} syncId
   */
  setSyncId(syncId) {
    this._syncId = syncId;
  },

  /**
   * Set the current batch identifier for inclusion in all log entries.
   * @param {string} batch - e.g. "a-d", "e-h"
   */
  setBatch(batch) {
    this._batch = batch;
  },

  /**
   * Clear batch context (between batches).
   */
  clearBatch() {
    this._batch = null;
  },

  // ─── ERROR level (always logged) ────────────────────────────────────────

  /**
   * Log an error. Always visible at all log levels.
   *
   * @param {string} component - Source module
   * @param {string} event     - Event code (e.g. USER_CREATE_FAILED)
   * @param {string} message   - Description
   * @param {Object} [data]    - Error details, stack trace, etc.
   */
  error(component, event, message, data) {
    log("ERROR", component, event, message, data);
  },

  /**
   * Log a conflict between AD and Cognito data.
   * Always visible — conflicts are treated as errors for alerting.
   *
   * @param {string} component
   * @param {string} message
   * @param {Object} data - Should include { field, adValue, cognitoValue, resolution }
   */
  conflict(component, message, data) {
    log("ERROR", component, "CONFLICT", message, data);
  },

  // ─── NORMAL level (connections, summaries, errors) ──────────────────────

  /**
   * Log a high-level informational event.
   * Visible at NORMAL and DEBUG levels.
   *
   * @param {string} component
   * @param {string} event
   * @param {string} message
   * @param {Object} [data]
   */
  info(component, event, message, data) {
    log("NORMAL", component, event, message, data);
  },

  /**
   * Log a batch summary with statistics.
   *
   * @param {string} message
   * @param {Object} stats
   */
  summary(component, message, stats) {
    log("NORMAL", component, "SUMMARY", message, stats);
  },

  // ─── DEBUG level (everything) ───────────────────────────────────────────

  /**
   * Log detailed debug information.
   * Only visible when LOG_LEVEL=DEBUG.
   *
   * @param {string} component
   * @param {string} event
   * @param {string} message
   * @param {Object} [data]
   */
  debug(component, event, message, data) {
    log("DEBUG", component, event, message, data);
  },

  // ─── Timing utilities ──────────────────────────────────────────────────

  /**
   * Start a timer and return a function that logs elapsed time.
   * The end function logs at NORMAL level.
   *
   * @param {string} component
   * @param {string} label - What is being timed
   * @returns {Function} Call with no args to stop timer and log duration
   */
  startTimer(component, label) {
    const start = Date.now();
    logger.debug(component, "TIMER_START", `Starting: ${label}`);

    return (extraData) => {
      const durationMs = Date.now() - start;
      logger.info(component, "TIMER_END", `${label} completed in ${durationMs}ms`, {
        durationMs,
        ...extraData,
      });
      return durationMs;
    };
  },

  // ─── Convenience methods for common events ──────────────────────────────

  /** Log successful connection to a service */
  connected(component, target) {
    this.info(component, "CONNECTED", `Connected to ${target}`);
  },

  /** Log disconnection from a service */
  disconnected(component, target) {
    this.info(component, "DISCONNECTED", `Disconnected from ${target}`);
  },

  /** Log batch processing start */
  batchStart(batchIndex, totalBatches, range) {
    this.setBatch(`${range.start}-${range.end}`);
    this.info("Sync", "BATCH_START",
      `Starting batch ${batchIndex + 1}/${totalBatches}: range [${range.start}-${range.end}]`,
      { batchIndex, totalBatches, range }
    );
  },

  /** Log batch processing end with stats */
  batchEnd(batchIndex, stats) {
    this.summary("Sync", `Batch ${batchIndex + 1} complete`, stats);
    this.clearBatch();
  },

  /** Log that a user was skipped due to delta sync (no changes) */
  deltaSkip(component, email, reason) {
    this.debug(component, "DELTA_SKIP", `Skipping unchanged user: ${email}`, { email, reason });
  },

  /** Log current log level on startup */
  logConfig() {
    const levelName = Object.entries(LOG_LEVELS).find(([, v]) => v === CURRENT_LEVEL)?.[0] || "NORMAL";
    this.info("Logger", "CONFIG", `Log level: ${levelName}`, {
      level: levelName,
      numericLevel: CURRENT_LEVEL,
    });
  },

  /** Expose level check for conditional expensive debug operations */
  isDebug() {
    return CURRENT_LEVEL >= LOG_LEVELS.DEBUG;
  },

  isNormal() {
    return CURRENT_LEVEL >= LOG_LEVELS.NORMAL;
  },
};

module.exports = logger;
