/**
 * sync-state.js
 * ==============
 * Manages sync state and delta timestamps in S3 for Lambda checkpoint/resume.
 *
 * TWO SEPARATE STATE FILES:
 *
 * 1. SYNC STATE (sync-state.json)
 *    Tracks which alphabetical batch the current sync run has reached.
 *    Reset when a sync run completes. Used for checkpoint/resume across
 *    Lambda invocations.
 *
 * 2. DELTA TIMESTAMPS (delta-timestamps.json)
 *    Persists the timestamp of the LAST COMPLETED sync run. On subsequent
 *    runs, users whose AD `whenChanged` AND Cognito `UserLastModifiedDate`
 *    are both older than this timestamp can be skipped — they haven't
 *    changed since the last sync.
 *
 *    IMPORTANT: The delta timestamp is only written when a FULL sync run
 *    completes (all batches). Partial runs do NOT update the delta, so
 *    an interrupted sync will re-process the batches it didn't finish.
 *
 * WHY DELTA SYNC MATTERS:
 *   On a 50,000-user directory where only 200 users change per day,
 *   delta sync reduces the write workload from 50,000 comparisons +
 *   writes to ~200, saving significant Cognito API costs and Lambda
 *   execution time.
 */

"use strict";

const { S3Client, GetObjectCommand, PutObjectCommand } = require("@aws-sdk/client-s3");
const config = require("./config");
const logger = require("./logger");

const s3 = new S3Client({});

/**
 * Alphabetical ranges for batching users.
 *
 * We split the alphabet into ranges so both AD and Cognito can be
 * queried with matching filters. Each range = one sync batch.
 */
const ALPHA_RANGES = [
  { start: "a", end: "d" },   // Batch 0
  { start: "e", end: "h" },   // Batch 1
  { start: "i", end: "l" },   // Batch 2
  { start: "m", end: "p" },   // Batch 3
  { start: "q", end: "s" },   // Batch 4
  { start: "t", end: "v" },   // Batch 5
  { start: "w", end: "z" },   // Batch 6
  { start: "0", end: "9" },   // Batch 7: numeric prefixes
];

// ─────────────────────────────────────────────────────────────────────────────
// Sync Run State (checkpoint/resume)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Load sync state from S3.
 * @returns {Promise<Object|null>}
 */
async function loadState() {
  try {
    const cmd = new GetObjectCommand({
      Bucket: config.sync.s3Bucket,
      Key: config.sync.s3StateKey,
    });
    const response = await s3.send(cmd);
    const body = await response.Body.transformToString();
    const state = JSON.parse(body);
    logger.info("State", "STATE_LOADED",
      `Loaded sync state: batch ${state.currentBatch}/${state.totalBatches}, status=${state.status}`,
      { syncId: state.syncId, currentBatch: state.currentBatch, status: state.status }
    );
    return state;
  } catch (err) {
    if (err.name === "NoSuchKey" || err.Code === "NoSuchKey") {
      logger.info("State", "STATE_NONE", "No existing sync state — starting fresh");
      return null;
    }
    logger.error("State", "STATE_LOAD_ERROR", `Failed to load state: ${err.message}`);
    throw err;
  }
}

/**
 * Save sync state to S3 (checkpoint after each batch).
 * @param {Object} state
 */
async function saveState(state) {
  state.lastUpdatedAt = new Date().toISOString();
  const cmd = new PutObjectCommand({
    Bucket: config.sync.s3Bucket,
    Key: config.sync.s3StateKey,
    Body: JSON.stringify(state, null, 2),
    ContentType: "application/json",
  });
  await s3.send(cmd);
  logger.info("State", "STATE_SAVED",
    `Checkpoint: batch ${state.currentBatch}/${state.totalBatches}`,
    { currentBatch: state.currentBatch }
  );
}

/**
 * Create a fresh sync state for a new sync run.
 * @returns {Object}
 */
function createInitialState() {
  return {
    syncId: new Date().toISOString(),
    status: "in_progress",
    currentBatch: 0,
    totalBatches: ALPHA_RANGES.length,
    stats: {
      usersCreatedInCognito: 0,
      usersCreatedInAD: 0,
      usersUpdatedInCognito: 0,
      groupsCreatedInCognito: 0,
      groupsCreatedInAD: 0,
      usersSkippedByDelta: 0,
      errors: [],
    },
    startedAt: new Date().toISOString(),
    lastUpdatedAt: new Date().toISOString(),
  };
}

/**
 * Mark the sync as complete. Also updates the delta timestamp
 * so the next run can skip unchanged users.
 *
 * @param {Object} state
 */
async function markComplete(state) {
  state.status = "complete";
  state.completedAt = new Date().toISOString();
  await saveState(state);

  // Update delta timestamp for next run
  if (config.delta.enabled) {
    await saveDeltaTimestamp(state.startedAt);
  }

  logger.info("State", "SYNC_COMPLETE", "Sync run marked as COMPLETE", {
    syncId: state.syncId,
    duration: `${Math.round((Date.now() - new Date(state.startedAt).getTime()) / 1000)}s`,
    stats: state.stats,
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// Delta Timestamps (skip unchanged users)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Load the last-completed-sync timestamp from S3.
 *
 * This is used to determine which users have changed since the last
 * successful sync and can be skipped.
 *
 * @returns {Promise<string|null>} ISO 8601 timestamp, or null if no prior sync
 */
async function loadDeltaTimestamp() {
  if (!config.delta.enabled) {
    logger.debug("Delta", "DISABLED", "Delta sync is disabled");
    return null;
  }

  try {
    const cmd = new GetObjectCommand({
      Bucket: config.sync.s3Bucket,
      Key: config.delta.s3Key,
    });
    const response = await s3.send(cmd);
    const body = await response.Body.transformToString();
    const data = JSON.parse(body);

    logger.info("Delta", "TIMESTAMP_LOADED",
      `Last successful sync: ${data.lastSyncCompleted}`,
      { lastSyncCompleted: data.lastSyncCompleted }
    );
    return data.lastSyncCompleted || null;
  } catch (err) {
    if (err.name === "NoSuchKey" || err.Code === "NoSuchKey") {
      logger.info("Delta", "TIMESTAMP_NONE",
        "No delta timestamp found — first run, all users will be processed"
      );
      return null;
    }
    logger.error("Delta", "TIMESTAMP_LOAD_ERROR", `Failed to load delta timestamp: ${err.message}`);
    throw err;
  }
}

/**
 * Save the delta timestamp after a FULL sync run completes.
 *
 * We use the sync START time (not end time) as the delta cutoff.
 * This ensures we don't miss changes that occurred during the sync.
 *
 * @param {string} syncStartedAt - ISO 8601 timestamp of when this sync began
 */
async function saveDeltaTimestamp(syncStartedAt) {
  const data = {
    lastSyncCompleted: syncStartedAt,
    savedAt: new Date().toISOString(),
  };

  const cmd = new PutObjectCommand({
    Bucket: config.sync.s3Bucket,
    Key: config.delta.s3Key,
    Body: JSON.stringify(data, null, 2),
    ContentType: "application/json",
  });

  await s3.send(cmd);
  logger.info("Delta", "TIMESTAMP_SAVED",
    `Delta timestamp saved: ${syncStartedAt}`,
    { lastSyncCompleted: syncStartedAt }
  );
}

/**
 * Create a sync-state instance bound to a specific config (multi-tenant use).
 * Each returned object has its own S3 key paths derived from config.tenantId.
 *
 * @param {Object} cfg - Config object from buildConfig()
 * @returns {Object} Sync state functions bound to the given config
 */
function createSyncState(cfg) {
  const bucket = cfg.sync.s3Bucket;
  const stateKey = cfg.sync.s3StateKey;
  const deltaKey = cfg.delta.s3Key;
  const deltaEnabled = cfg.delta.enabled;

  async function _loadState() {
    try {
      const cmd = new GetObjectCommand({ Bucket: bucket, Key: stateKey });
      const response = await s3.send(cmd);
      const body = await response.Body.transformToString();
      const state = JSON.parse(body);
      logger.info("State", "STATE_LOADED",
        `Loaded sync state: batch ${state.currentBatch}/${state.totalBatches}, status=${state.status}`,
        { syncId: state.syncId, currentBatch: state.currentBatch, status: state.status, tenantId: cfg.tenantId }
      );
      return state;
    } catch (err) {
      if (err.name === "NoSuchKey" || err.Code === "NoSuchKey") {
        logger.info("State", "STATE_NONE", "No existing sync state — starting fresh", { tenantId: cfg.tenantId });
        return null;
      }
      logger.error("State", "STATE_LOAD_ERROR", `Failed to load state: ${err.message}`, { tenantId: cfg.tenantId });
      throw err;
    }
  }

  async function _saveState(state) {
    state.lastUpdatedAt = new Date().toISOString();
    const cmd = new PutObjectCommand({
      Bucket: bucket, Key: stateKey,
      Body: JSON.stringify(state, null, 2), ContentType: "application/json",
    });
    await s3.send(cmd);
    logger.info("State", "STATE_SAVED",
      `Checkpoint: batch ${state.currentBatch}/${state.totalBatches}`,
      { currentBatch: state.currentBatch, tenantId: cfg.tenantId }
    );
  }

  async function _markComplete(state) {
    state.status = "complete";
    state.completedAt = new Date().toISOString();
    await _saveState(state);
    if (deltaEnabled) await _saveDeltaTimestamp(state.startedAt);
    logger.info("State", "SYNC_COMPLETE", "Sync run marked as COMPLETE", {
      syncId: state.syncId, tenantId: cfg.tenantId,
      duration: `${Math.round((Date.now() - new Date(state.startedAt).getTime()) / 1000)}s`,
      stats: state.stats,
    });
  }

  async function _loadDeltaTimestamp() {
    if (!deltaEnabled) {
      logger.debug("Delta", "DISABLED", "Delta sync is disabled", { tenantId: cfg.tenantId });
      return null;
    }
    try {
      const cmd = new GetObjectCommand({ Bucket: bucket, Key: deltaKey });
      const response = await s3.send(cmd);
      const body = await response.Body.transformToString();
      const data = JSON.parse(body);
      logger.info("Delta", "TIMESTAMP_LOADED",
        `Last successful sync: ${data.lastSyncCompleted}`, { lastSyncCompleted: data.lastSyncCompleted, tenantId: cfg.tenantId });
      return data.lastSyncCompleted || null;
    } catch (err) {
      if (err.name === "NoSuchKey" || err.Code === "NoSuchKey") {
        logger.info("Delta", "TIMESTAMP_NONE",
          "No delta timestamp found — first run", { tenantId: cfg.tenantId });
        return null;
      }
      logger.error("Delta", "TIMESTAMP_LOAD_ERROR", `Failed to load delta timestamp: ${err.message}`, { tenantId: cfg.tenantId });
      throw err;
    }
  }

  async function _saveDeltaTimestamp(syncStartedAt) {
    const data = { lastSyncCompleted: syncStartedAt, savedAt: new Date().toISOString() };
    const cmd = new PutObjectCommand({
      Bucket: bucket, Key: deltaKey,
      Body: JSON.stringify(data, null, 2), ContentType: "application/json",
    });
    await s3.send(cmd);
    logger.info("Delta", "TIMESTAMP_SAVED",
      `Delta timestamp saved: ${syncStartedAt}`, { lastSyncCompleted: syncStartedAt, tenantId: cfg.tenantId });
  }

  return {
    ALPHA_RANGES,
    loadState: _loadState,
    saveState: _saveState,
    createInitialState,
    markComplete: _markComplete,
    loadDeltaTimestamp: _loadDeltaTimestamp,
    saveDeltaTimestamp: _saveDeltaTimestamp,
  };
}

module.exports = {
  ALPHA_RANGES,
  loadState,
  saveState,
  createInitialState,
  markComplete,
  loadDeltaTimestamp,
  saveDeltaTimestamp,
  createSyncState,
};
