/**
 * providers/index.js
 * ===================
 * Provider factory — returns the correct LDAP provider instance
 * based on the LDAP_PROVIDER environment variable.
 *
 * USAGE IN SYNC ENGINE:
 *   const { getProvider } = require("./providers");
 *   const ldap = getProvider();    // Returns AdProvider or GenericLdapProvider
 *   const users = await ldap.fetchUsersByRange("a", "d");
 *
 * SUPPORTED PROVIDERS:
 *   LDAP_PROVIDER=ad       → Active Directory (default)
 *   LDAP_PROVIDER=generic  → Generic LDAP (OpenLDAP, 389DS, FreeIPA, etc.)
 *
 * The provider is a singleton — the same instance is returned on every
 * call to getProvider() within a Lambda invocation. This ensures the
 * LDAP connection is reused.
 */

"use strict";

const config = require("../config");
const logger = require("../logger");

const AdProvider = require("./ad-provider");
const GenericLdapProvider = require("./generic-ldap-provider");

/** @type {import('./ldap-base')|null} Singleton provider instance */
let _provider = null;

/**
 * Get the configured LDAP provider instance.
 *
 * @returns {import('./ldap-base')} Provider implementing the full LDAP interface
 */
function getProvider() {
  if (_provider) return _provider;

  const providerType = config.ldap.provider;

  switch (providerType) {
    case "ad":
      _provider = new AdProvider();
      logger.info("Provider", "INITIALIZED",
        "Using Active Directory provider", { provider: "ad" });
      break;

    case "generic":
      _provider = new GenericLdapProvider();
      logger.info("Provider", "INITIALIZED",
        "Using Generic LDAP provider", {
          provider: "generic",
          userObjectClass: config.ldap.generic.userObjectClass,
          groupObjectClass: config.ldap.generic.groupObjectClass,
          uniqueIdAttr: config.ldap.generic.uniqueIdAttr,
        });
      break;

    default:
      throw new Error(
        `Unknown LDAP provider: "${providerType}". ` +
        `Set LDAP_PROVIDER to "ad" or "generic".`
      );
  }

  return _provider;
}

/**
 * Reset the provider singleton (used for testing or reconfiguration).
 */
function resetProvider() {
  if (_provider) {
    _provider.disconnect().catch(() => {});
    _provider = null;
  }
}

/**
 * Create a new provider instance with the given config (multi-tenant use).
 * Does NOT use the module-level singleton — each call returns a fresh instance.
 *
 * @param {Object} cfg - Config object from buildConfig()
 * @returns {import('./ldap-base')} Provider instance
 */
function createProvider(cfg) {
  const providerType = cfg.ldap.provider;

  switch (providerType) {
    case "ad":
      logger.info("Provider", "INITIALIZED",
        "Creating AD provider instance", { provider: "ad", tenantId: cfg.tenantId });
      return new AdProvider(cfg);

    case "generic":
      logger.info("Provider", "INITIALIZED",
        "Creating Generic LDAP provider instance", {
          provider: "generic",
          tenantId: cfg.tenantId,
          userObjectClass: cfg.ldap.generic.userObjectClass,
        });
      return new GenericLdapProvider(cfg);

    default:
      throw new Error(
        `Unknown LDAP provider: "${providerType}". ` +
        `Set ldapProvider to "ad" or "generic".`
      );
  }
}

module.exports = { getProvider, resetProvider, createProvider };
