/**
 * providers/ldap-base.js
 * =======================
 * Abstract base class for LDAP directory providers.
 *
 * This module contains ALL shared LDAP functionality:
 *   • Client creation, binding, and connection management
 *   • Paged search execution
 *   • Alphabetical range filter construction
 *   • Rate-limited search helper
 *
 * Subclasses (AD, Generic LDAP) override abstract methods to provide
 * directory-specific behaviour:
 *   • User search filter and attribute mapping
 *   • Group search filter and attribute mapping
 *   • User creation (password encoding, account activation)
 *   • Group creation
 *   • Unique ID extraction (objectGUID vs entryUUID)
 *   • Timestamp parsing (whenChanged vs modifyTimestamp)
 *
 * PROVIDER CONTRACT:
 *   Every provider must implement these methods:
 *
 *   fetchUsersByRange(startChar, endChar) → Promise<Array<NormalisedUser>>
 *   fetchSecurityGroups()                 → Promise<Array<{name, dn}>>
 *   createUser(user)                      → Promise<NormalisedUser>
 *   readUserByEmail(email)                → Promise<NormalisedUser|null>
 *   createSecurityGroup(groupName)        → Promise<string> (DN)
 *   addUserToGroup(userDn, groupDn)       → Promise<void>
 *   disconnect()                          → Promise<void>
 *   getProviderName()                     → string
 *
 * NORMALISED USER SHAPE:
 *   {
 *     email:          string,   // lowercase, trimmed
 *     firstName:      string,
 *     lastName:       string,
 *     location:       string,
 *     mobile:         string,
 *     voice:          string,
 *     altEmail:       string,   // semicolon-separated if multiple
 *     uniqueId:       string,   // directory-native unique ID (GUID string or UUID)
 *     immutableId:    string,   // base64 encoded (AD) or same as uniqueId (generic)
 *     securityGroups: string[], // group common names
 *     dn:             string,   // distinguished name
 *     whenChanged:    string|null, // ISO 8601 timestamp for delta sync
 *   }
 */

"use strict";

const ldap = require("ldapjs");
const defaultConfig = require("../config");
const logger = require("../logger");

class LdapBaseProvider {
  /**
   * @param {Object} [config] - Optional config override for multi-tenant use.
   *                             Falls back to the module-level singleton.
   */
  constructor(config) {
    this._config = config || defaultConfig;
    /** @type {ldap.Client|null} Reusable LDAP client */
    this._client = null;
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Connection Management (shared by all providers)
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Create and bind an LDAP client. Reuses existing connection if still open.
   *
   * @returns {Promise<ldap.Client>} Authenticated LDAP client
   */
  async getClient() {
    if (this._client) return this._client;

    const providerName = this.getProviderName();
    logger.debug(providerName, "CONNECTING", `Connecting to ${this._config.ldap.url}`);

    this._client = ldap.createClient({
      url: this._config.ldap.url,
      connectTimeout: 10_000,
      timeout: 30_000,
      tlsOptions: this._config.ldap.tlsOptions,
    });

    this._client.on("error", (err) => {
      logger.error(providerName, "CONNECTION_ERROR",
        `LDAP connection error: ${err.message}`,
        { url: this._config.ldap.url, errorCode: err.code }
      );
      this._client = null;
    });

    await new Promise((resolve, reject) =>
      this._client.bind(this._config.ldap.bindDN, this._config.ldap.bindPassword, (err) =>
        err ? reject(err) : resolve()
      )
    );

    logger.connected(providerName, this._config.ldap.url);
    return this._client;
  }

  /**
   * Cleanly unbind and destroy the LDAP client.
   */
  async disconnect() {
    if (this._client) {
      try { this._client.unbind(); } catch (_) { /* ignore */ }
      this._client = null;
      logger.disconnected(this.getProviderName(), this._config.ldap.url);
    }
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Search Helpers (shared)
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Execute a paged LDAP search and collect all entries.
   *
   * Handles RFC 2696 server-side paging automatically via ldapjs.
   *
   * @param {string} baseDN     - Search base
   * @param {string} filter     - LDAP filter string
   * @param {string[]} attributes - Attributes to return
   * @param {number} [pageSize=1000] - Server-side page size
   * @returns {Promise<Array<Object>>} Raw ldapjs entry objects
   */
  async pagedSearch(baseDN, filter, attributes, pageSize = 1000) {
    const client = await this.getClient();
    const providerName = this.getProviderName();

    logger.debug(providerName, "PAGED_SEARCH_START", `LDAP search starting`, {
      baseDN, filter, attributeCount: attributes.length, pageSize,
    });

    return new Promise((resolve, reject) => {
      const entries = [];
      let referralCount = 0;

      client.search(baseDN, {
        scope: "sub",
        filter,
        attributes,
        paged: true,
      }, (err, res) => {
        if (err) {
          logger.error(providerName, "SEARCH_ERROR",
            `Search failed: ${err.message}`, { baseDN, filter, errorCode: err.code, errorName: err.name });
          return reject(err);
        }

        // Log what type of response object we got
        logger.debug(providerName, "SEARCH_RES_TYPE", `Search response type: ${res?.constructor?.name}`, {
          hasOn: typeof res?.on === 'function',
          events: Object.keys(res?._events || {}),
        });

        res.on("searchEntry", (entry) => {
          entries.push(entry);
          if (entries.length <= 3) {
            // Log first few entries for debugging
            const attrNames = entry.attributes?.map(a => a.type) || [];
            logger.debug(providerName, "SEARCH_ENTRY_RECEIVED", `Entry #${entries.length}`, { attrNames });
          }
        });

        res.on("searchReference", (referral) => {
          referralCount++;
          logger.info(providerName, "SEARCH_REFERRAL", `Referral received #${referralCount}`, {
            uris: referral?.uris || referral?.toString?.() || JSON.stringify(referral),
          });
        });

        res.on("error", (err) => {
          logger.error(providerName, "SEARCH_STREAM_ERROR",
            `Stream error: ${err.message}`, { baseDN, filter, errorCode: err.code });
          reject(err);
        });

        res.on("end", (result) => {
          logger.info(providerName, "PAGED_SEARCH_COMPLETE", `LDAP search returned ${entries.length} entries`, {
            baseDN, entryCount: entries.length, referralCount, status: result?.status,
          });
          resolve(entries);
        });
      });
    });
  }

  /**
   * Build an LDAP OR-filter matching an email attribute whose value
   * starts with any character in the given range.
   *
   * Example for range a–d with emailAttr="mail":
   *   (|(mail=a*)(mail=A*)(mail=b*)(mail=B*)...(mail=d*)(mail=D*))
   *
   * @param {string} emailAttr - LDAP attribute name for email
   * @param {string} startChar - Inclusive start
   * @param {string} endChar   - Inclusive end
   * @returns {string} LDAP OR-filter fragment
   */
  buildAlphaRangeFilter(emailAttr, startChar, endChar) {
    const parts = [];
    for (
      let c = startChar.toLowerCase().charCodeAt(0);
      c <= endChar.toLowerCase().charCodeAt(0);
      c++
    ) {
      const ch = String.fromCharCode(c);
      parts.push(`(${emailAttr}=${ch}*)`);
      parts.push(`(${emailAttr}=${ch.toUpperCase()}*)`);
    }
    return `(|${parts.join("")})`;
  }

  /**
   * Extract a group's common name from its full distinguished name.
   * "CN=Sales Team,OU=Groups,DC=example,DC=com" → "Sales Team"
   *
   * @param {string} dn
   * @returns {string|null}
   */
  extractGroupCN(dn) {
    const match = dn.match(/^CN=([^,]+)/i);
    return match ? match[1] : null;
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Abstract Methods — MUST be implemented by subclasses
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Return a human-readable name for this provider.
   * Used in log messages (e.g. "AD", "LDAP").
   * @abstract
   * @returns {string}
   */
  getProviderName() {
    throw new Error("Subclass must implement getProviderName()");
  }

  /**
   * Fetch users whose email starts with characters in [startChar, endChar].
   * Must return normalised user objects sorted by email.
   * @abstract
   * @param {string} startChar
   * @param {string} endChar
   * @returns {Promise<Array<Object>>}
   */
  async fetchUsersByRange(startChar, endChar) {
    throw new Error("Subclass must implement fetchUsersByRange()");
  }

  /**
   * Fetch all security/posix groups.
   * @abstract
   * @returns {Promise<Array<{name: string, dn: string}>>}
   */
  async fetchSecurityGroups() {
    throw new Error("Subclass must implement fetchSecurityGroups()");
  }

  /**
   * Create a user in the directory.
   * Must return the created user with uniqueId populated (read back).
   * @abstract
   * @param {Object} user - Normalised user object
   * @returns {Promise<Object>} Created user with uniqueId/immutableId
   */
  async createUser(user) {
    throw new Error("Subclass must implement createUser()");
  }

  /**
   * Read a single user by email.
   * @abstract
   * @param {string} email
   * @returns {Promise<Object|null>}
   */
  async readUserByEmail(email) {
    throw new Error("Subclass must implement readUserByEmail()");
  }

  /**
   * Create a security group.
   * @abstract
   * @param {string} groupName
   * @returns {Promise<string>} DN of the created group
   */
  async createSecurityGroup(groupName) {
    throw new Error("Subclass must implement createSecurityGroup()");
  }

  /**
   * Add a user to a group.
   * @abstract
   * @param {string} userDn
   * @param {string} groupDn
   * @returns {Promise<void>}
   */
  async addUserToGroup(userDn, groupDn) {
    throw new Error("Subclass must implement addUserToGroup()");
  }
}

module.exports = LdapBaseProvider;
