/**
 * cognito-utils.js
 * =================
 * AWS Cognito User Pool helper functions for the two-way sync.
 *
 * Responsibilities:
 *   • List/search users from a Cognito User Pool in alphabetical batches
 *   • List all Cognito groups (used as security group equivalents)
 *   • Create users in Cognito (via AdminCreateUser)
 *   • Update user attributes (via AdminUpdateUserAttributes)
 *   • Create groups in Cognito
 *   • Add users to groups
 *   • Expose `UserLastModifiedDate` for delta sync comparison
 *
 * COST NOTES:
 *   - ListUsers / AdminGetUser = READ operations → lower cost
 *   - AdminCreateUser / AdminUpdateUserAttributes = WRITE operations → higher cost
 *   - We collect all changes before writing to minimise write API calls
 *   - Each user is written to AT MOST ONCE per sync cycle
 *
 * DELTA SYNC NOTE:
 *   Cognito's ListUsers response includes `UserLastModifiedDate` on each
 *   user object. We expose this as `lastModified` (ISO 8601 string) so
 *   the sync engine can compare it against AD's `whenChanged` and the
 *   last-sync timestamp to skip unchanged users.
 *
 * COGNITO API LIMITS:
 *   - ListUsers:                   ~30 req/sec (soft limit)
 *   - AdminCreateUser:             ~50 req/sec (soft limit)
 *   - AdminUpdateUserAttributes:   ~25 req/sec (soft limit)
 *   - ListUsers returns max 60 users per page
 */

"use strict";

const {
  CognitoIdentityProviderClient,
  ListUsersCommand,
  AdminGetUserCommand,
  AdminCreateUserCommand,
  AdminUpdateUserAttributesCommand,
  AdminAddUserToGroupCommand,
  AdminSetUserPasswordCommand,
  AdminLinkProviderForUserCommand,
  ListGroupsCommand,
  CreateGroupCommand,
  AdminListGroupsForUserCommand,
} = require("@aws-sdk/client-cognito-identity-provider");

const config = require("./config");
const logger = require("./logger");

// ─────────────────────────────────────────────────────────────────────────────
// Cognito Client (singleton — uses Lambda execution role credentials)
// ─────────────────────────────────────────────────────────────────────────────

const cognitoClient = new CognitoIdentityProviderClient({});

// ─────────────────────────────────────────────────────────────────────────────
// User Retrieval
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Fetch all Cognito users whose email starts with characters in the
 * given alphabetical range [startChar, endChar].
 *
 * We iterate each letter and page through results. For each user we also
 * fetch group memberships (additional API call per user).
 *
 * The returned objects include `lastModified` (from Cognito's
 * UserLastModifiedDate) for delta sync filtering.
 *
 * @param {string} startChar - Inclusive start character (e.g. 'a')
 * @param {string} endChar   - Inclusive end character (e.g. 'd')
 * @returns {Promise<Array<Object>>} Normalised user objects sorted by email
 */
async function fetchUsersByRange(startChar, endChar) {
  const f = config.cognito.fields;
  const allUsers = [];
  const timer = logger.startTimer("Cognito", `Fetch users [${startChar}-${endChar}]`);

  for (let c = startChar.toLowerCase().charCodeAt(0); c <= endChar.toLowerCase().charCodeAt(0); c++) {
    const prefix = String.fromCharCode(c);
    let paginationToken = undefined;
    let pageCount = 0;

    do {
      const cmd = new ListUsersCommand({
        UserPoolId: config.cognito.userPoolId,
        Filter: `email ^= "${prefix}"`,
        Limit: 60,
        PaginationToken: paginationToken,
      });

      logger.debug("Cognito", "LIST_PAGE", `Listing users: email ^= "${prefix}" (page ${++pageCount})`);

      const response = await cognitoClient.send(cmd);
      paginationToken = response.PaginationToken;

      for (const cognitoUser of response.Users || []) {
        const attrs = {};
        (cognitoUser.Attributes || []).forEach((a) => { attrs[a.Name] = a.Value; });

        const email = (attrs[f.email] || attrs["email"] || "").toLowerCase().trim();
        if (!email) continue;

        // Fetch group memberships for this user
        const groups = await fetchUserGroups(cognitoUser.Username);

        // Cognito provides UserLastModifiedDate as a JS Date object
        const lastModified = cognitoUser.UserLastModifiedDate
          ? cognitoUser.UserLastModifiedDate.toISOString()
          : null;

        const user = {
          email,
          username: cognitoUser.Username,
          firstName: attrs[f.firstName] || "",
          lastName: attrs[f.lastName] || "",
          location: attrs[f.location] || "",
          mobile: attrs[f.mobile] || "",
          voice: attrs[f.voice] || "",
          altEmail: attrs[f.altEmail] || "",
          immutableId: attrs[f.immutableId] || "",
          securityGroups: groups,
          status: cognitoUser.UserStatus,
          enabled: cognitoUser.Enabled,
          lastModified,
        };

        logger.debug("Cognito", "USER_FOUND", `Found: ${email}`, {
          email, lastModified, groups: groups.length, status: cognitoUser.UserStatus,
        });

        allUsers.push(user);
      }

      await sleep(50); // Respect rate limits (~30 req/sec)
    } while (paginationToken);
  }

  allUsers.sort((a, b) => a.email.localeCompare(b.email));
  timer({ userCount: allUsers.length });
  return allUsers;
}

/**
 * Fetch group memberships for a single Cognito user.
 *
 * @param {string} username - Cognito Username
 * @returns {Promise<string[]>} Array of group names
 */
async function fetchUserGroups(username) {
  const groups = [];
  let nextToken = undefined;

  do {
    const cmd = new AdminListGroupsForUserCommand({
      UserPoolId: config.cognito.userPoolId,
      Username: username,
      Limit: 60,
      NextToken: nextToken,
    });

    const response = await cognitoClient.send(cmd);
    nextToken = response.NextToken;

    (response.Groups || []).forEach((g) => {
      if (g.GroupName) groups.push(g.GroupName);
    });
  } while (nextToken);

  return groups;
}

// ─────────────────────────────────────────────────────────────────────────────
// Group Retrieval
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Fetch all groups defined in the Cognito User Pool.
 *
 * @returns {Promise<Array<{name: string, description: string}>>}
 */
async function fetchAllGroups() {
  const groups = [];
  let nextToken = undefined;
  const timer = logger.startTimer("Cognito", "Fetch all groups");

  do {
    const cmd = new ListGroupsCommand({
      UserPoolId: config.cognito.userPoolId,
      Limit: 60,
      NextToken: nextToken,
    });

    const response = await cognitoClient.send(cmd);
    nextToken = response.NextToken;

    (response.Groups || []).forEach((g) => {
      groups.push({ name: g.GroupName, description: g.Description || "" });
      logger.debug("Cognito", "GROUP_FOUND", `Found group: ${g.GroupName}`);
    });
  } while (nextToken);

  timer({ groupCount: groups.length });
  return groups;
}

// ─────────────────────────────────────────────────────────────────────────────
// User Creation
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Create a new user in Cognito.
 *
 * Uses SUPPRESS for MessageAction to avoid sending invitation emails
 * during bulk sync.
 *
 * @param {Object} user - Normalised user object
 * @returns {Promise<Object>} Cognito response
 */
async function createUser(user) {
  const f = config.cognito.fields;

  const attributes = [];
  const addAttr = (name, value) => {
    if (value) attributes.push({ Name: name, Value: String(value) });
  };

  addAttr(f.email, user.email);
  addAttr("email_verified", "true");
  addAttr(f.firstName, user.firstName);
  addAttr(f.lastName, user.lastName);
  addAttr(f.location, user.location);
  addAttr(f.mobile, user.mobile);
  addAttr(f.voice, user.voice);
  addAttr(f.altEmail, user.altEmail);
  addAttr(f.immutableId, user.immutableId);

  logger.debug("Cognito", "USER_CREATING", `Creating: ${user.email}`, {
    email: user.email, attributeCount: attributes.length,
  });

  const cmd = new AdminCreateUserCommand({
    UserPoolId: config.cognito.userPoolId,
    Username: user.email,
    UserAttributes: attributes,
    MessageAction: "SUPPRESS",
    DesiredDeliveryMediums: ["EMAIL"],
  });

  const response = await cognitoClient.send(cmd);
  logger.info("Cognito", "USER_CREATED", `Created user: ${user.email}`, { email: user.email });

  // Link with apersona OIDC provider so user can login via Hosted UI
  try {
    await cognitoClient.send(new AdminLinkProviderForUserCommand({
      Username: response.User.Username,
      UserPoolId: config.cognito.userPoolId,
      DestinationUser: {
        ProviderName: "Cognito",
        ProviderAttributeName: "email",
        ProviderAttributeValue: user.email.toLowerCase(),
      },
      SourceUser: {
        ProviderName: "apersona",
        ProviderAttributeName: "email",
        ProviderAttributeValue: user.email.toLowerCase(),
      },
    }));
    logger.debug("Cognito", "USER_LINKED", `Linked with apersona provider: ${user.email}`);
  } catch (linkErr) {
    logger.error("Cognito", "USER_LINK_FAILED",
      `Failed to link ${user.email} with apersona: ${linkErr.message}`,
      { email: user.email, error: linkErr.message });
  }

  await sleep(30); // Rate limit (~50 req/sec)
  return response;
}

/**
 * Create multiple users in Cognito. Processes sequentially with rate-limit delays.
 * Collects errors without stopping the entire batch.
 *
 * @param {Array<Object>} users
 * @returns {Promise<{created: string[], errors: Array<{email: string, error: string}>}>}
 */
async function batchCreateUsers(users) {
  const results = { created: [], errors: [] };

  for (const user of users) {
    try {
      await createUser(user);
      results.created.push(user.email);

      for (const group of user.securityGroups || []) {
        try {
          await addUserToGroup(user.email, group);
        } catch (groupErr) {
          logger.error("Cognito", "GROUP_ADD_WARN", `Could not add ${user.email} to ${group}`, {
            email: user.email, group, error: groupErr.message,
          });
        }
      }
    } catch (err) {
      if (err.name === "UsernameExistsException") {
        logger.debug("Cognito", "USER_EXISTS", `${user.email} already exists, updating`, { email: user.email });
        try {
          await updateUserAttributes(user);
          results.created.push(user.email);
        } catch (updateErr) {
          logger.error("Cognito", "USER_UPDATE_FAILED", `Update fallback failed: ${user.email}`, {
            email: user.email, error: updateErr.message,
          });
          results.errors.push({ email: user.email, error: updateErr.message });
        }
      } else {
        logger.error("Cognito", "USER_CREATE_FAILED", `Failed to create ${user.email}: ${err.message}`, {
          email: user.email, error: err.message, errorName: err.name,
        });
        results.errors.push({ email: user.email, error: err.message });
      }
    }
  }

  return results;
}

// ─────────────────────────────────────────────────────────────────────────────
// User Update
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Update attributes for an existing Cognito user. WRITE operation —
 * called at most once per user per sync cycle.
 *
 * @param {Object} user - Normalised user with all attributes to set
 */
async function updateUserAttributes(user) {
  const f = config.cognito.fields;

  const attributes = [];
  const addAttr = (name, value) => {
    if (value !== undefined && value !== null) {
      attributes.push({ Name: name, Value: String(value) });
    }
  };

  addAttr(f.firstName, user.firstName);
  addAttr(f.lastName, user.lastName);
  addAttr(f.location, user.location);
  addAttr(f.mobile, user.mobile);
  addAttr(f.voice, user.voice);
  addAttr(f.altEmail, user.altEmail);
  if (user.immutableId) addAttr(f.immutableId, user.immutableId);

  if (attributes.length === 0) {
    logger.debug("Cognito", "UPDATE_SKIP", `No attributes to update for ${user.email}`);
    return;
  }

  logger.debug("Cognito", "USER_UPDATING", `Updating: ${user.email}`, {
    email: user.email, attributeCount: attributes.length,
    attributes: attributes.map((a) => a.Name),
  });

  const cmd = new AdminUpdateUserAttributesCommand({
    UserPoolId: config.cognito.userPoolId,
    Username: user.email,
    UserAttributes: attributes,
  });

  await cognitoClient.send(cmd);
  logger.info("Cognito", "USER_UPDATED", `Updated: ${user.email}`, { email: user.email });

  await sleep(50); // Rate limit (~25 req/sec)
}

/**
 * Batch update user attributes. Single-pass "write once" function.
 *
 * @param {Array<Object>} users
 * @returns {Promise<{updated: string[], errors: Array<{email: string, error: string}>}>}
 */
async function batchUpdateUserAttributes(users) {
  const results = { updated: [], errors: [] };

  for (const user of users) {
    try {
      await updateUserAttributes(user);
      results.updated.push(user.email);

      for (const group of user.securityGroups || []) {
        try {
          await addUserToGroup(user.email, group);
        } catch (groupErr) {
          logger.error("Cognito", "GROUP_ADD_WARN", `Could not add ${user.email} to ${group}`, {
            email: user.email, group, error: groupErr.message,
          });
        }
      }
    } catch (err) {
      logger.error("Cognito", "USER_UPDATE_FAILED", `Failed to update ${user.email}: ${err.message}`, {
        email: user.email, error: err.message,
      });
      results.errors.push({ email: user.email, error: err.message });
    }
  }

  return results;
}

// ─────────────────────────────────────────────────────────────────────────────
// Group Management
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Create a group in Cognito if it doesn't already exist.
 */
async function createGroup(groupName, description) {
  try {
    const cmd = new CreateGroupCommand({
      UserPoolId: config.cognito.userPoolId,
      GroupName: groupName,
      Description: description || `Synced from AD: ${groupName}`,
    });
    await cognitoClient.send(cmd);
    logger.info("Cognito", "GROUP_CREATED", `Created group: ${groupName}`, { groupName });
  } catch (err) {
    if (err.name === "GroupExistsException") {
      logger.debug("Cognito", "GROUP_EXISTS", `Group already exists: ${groupName}`);
      return;
    }
    throw err;
  }
}

/**
 * Add a user to a Cognito group.
 */
async function addUserToGroup(username, groupName) {
  await createGroup(groupName); // Ensure group exists

  const cmd = new AdminAddUserToGroupCommand({
    UserPoolId: config.cognito.userPoolId,
    Username: username,
    GroupName: groupName,
  });

  await cognitoClient.send(cmd);
  logger.debug("Cognito", "GROUP_MEMBER_ADDED", `Added ${username} to ${groupName}`, { username, groupName });
  await sleep(30);
}

// ─────────────────────────────────────────────────────────────────────────────
// Utility
// ─────────────────────────────────────────────────────────────────────────────

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Convert email to Cognito username format.
 * Cognito User Pools configured with email alias don't allow email-format usernames.
 * This matches the admin GUI's user creation logic:
 *   email.replace('@', '_').replace('.', '_').toLowerCase()
 *
 * Example: "min@weaveai.net" → "min_weaveai_net"
 *
 * @param {string} email
 * @returns {string} Cognito-compatible username
 */
function emailToUsername(email) {
  if (!email) return email;
  return email.replace(/@/g, '_').replace(/\./g, '_').toLowerCase();
}

/**
 * Create a cognito-utils instance bound to a specific config (multi-tenant use).
 * All returned functions use the given config's userPoolId and field mappings.
 *
 * @param {Object} cfg - Config object from buildConfig()
 * @returns {Object} Cognito utility functions bound to the given config
 */
function createCognitoUtils(cfg) {
  const client = new CognitoIdentityProviderClient({});
  const f = cfg.cognito.fields;
  const poolId = cfg.cognito.userPoolId;

  async function _fetchUserGroups(username) {
    const groups = [];
    let nextToken = undefined;
    do {
      const cmd = new AdminListGroupsForUserCommand({
        UserPoolId: poolId, Username: username, Limit: 60, NextToken: nextToken,
      });
      const response = await client.send(cmd);
      nextToken = response.NextToken;
      (response.Groups || []).forEach((g) => { if (g.GroupName) groups.push(g.GroupName); });
    } while (nextToken);
    return groups;
  }

  async function _adminGetUser(username) {
    logger.debug("Cognito", "ADMIN_GET_USER", `Getting user: ${username}`, { username, tenantId: cfg.tenantId });
    const cmd = new AdminGetUserCommand({ UserPoolId: poolId, Username: username });
    const cognitoUser = await client.send(cmd);

    const attrs = {};
    (cognitoUser.UserAttributes || []).forEach((a) => { attrs[a.Name] = a.Value; });
    const email = (attrs[f.email] || attrs["email"] || "").toLowerCase().trim();
    const groups = await _fetchUserGroups(cognitoUser.Username);
    const lastModified = cognitoUser.UserLastModifiedDate ? cognitoUser.UserLastModifiedDate.toISOString() : null;

    return {
      email, username: cognitoUser.Username,
      firstName: attrs[f.firstName] || "", lastName: attrs[f.lastName] || "",
      location: attrs[f.location] || "", mobile: attrs[f.mobile] || "",
      voice: attrs[f.voice] || "", altEmail: attrs[f.altEmail] || "",
      immutableId: attrs[f.immutableId] || "", securityGroups: groups,
      status: cognitoUser.UserStatus, enabled: cognitoUser.Enabled, lastModified,
    };
  }

  async function _fetchUsersByRange(startChar, endChar) {
    const allUsers = [];
    const timer = logger.startTimer("Cognito", `Fetch users [${startChar}-${endChar}]`);

    logger.info("Cognito", "SEARCH_START", `Searching Cognito users [${startChar}-${endChar}]`, {
      tenantId: cfg.tenantId, userPoolId: poolId, range: `${startChar}-${endChar}`,
    });

    for (let c = startChar.toLowerCase().charCodeAt(0); c <= endChar.toLowerCase().charCodeAt(0); c++) {
      const prefix = String.fromCharCode(c);
      let paginationToken = undefined;
      let pageCount = 0;
      let prefixCount = 0;
      do {
        const cmd = new ListUsersCommand({
          UserPoolId: poolId, Filter: `email ^= "${prefix}"`, Limit: 60, PaginationToken: paginationToken,
        });
        logger.debug("Cognito", "LIST_PAGE", `Listing users: email ^= "${prefix}" (page ${++pageCount})`, { tenantId: cfg.tenantId });
        const response = await client.send(cmd);
        paginationToken = response.PaginationToken;
        for (const cognitoUser of response.Users || []) {
          const attrs = {};
          (cognitoUser.Attributes || []).forEach((a) => { attrs[a.Name] = a.Value; });
          const email = (attrs[f.email] || attrs["email"] || "").toLowerCase().trim();
          if (!email) continue;
          const groups = await _fetchUserGroups(cognitoUser.Username);
          const lastModified = cognitoUser.UserLastModifiedDate ? cognitoUser.UserLastModifiedDate.toISOString() : null;
          allUsers.push({
            email, username: cognitoUser.Username,
            firstName: attrs[f.firstName] || "", lastName: attrs[f.lastName] || "",
            location: attrs[f.location] || "", mobile: attrs[f.mobile] || "",
            voice: attrs[f.voice] || "", altEmail: attrs[f.altEmail] || "",
            immutableId: attrs[f.immutableId] || "", securityGroups: groups,
            status: cognitoUser.UserStatus, enabled: cognitoUser.Enabled, lastModified,
          });
          prefixCount++;
        }
        await sleep(50);
      } while (paginationToken);
      if (prefixCount > 0) {
        logger.info("Cognito", "PREFIX_RESULT", `Prefix "${prefix}": found ${prefixCount} users`, { tenantId: cfg.tenantId, prefix, count: prefixCount });
      }
    }
    allUsers.sort((a, b) => a.email.localeCompare(b.email));
    logger.info("Cognito", "SEARCH_COMPLETE", `Cognito search [${startChar}-${endChar}] complete: ${allUsers.length} users found`, {
      tenantId: cfg.tenantId, totalUsers: allUsers.length, range: `${startChar}-${endChar}`,
      emails: allUsers.map(u => u.email),
    });
    timer({ userCount: allUsers.length });
    return allUsers;
  }

  async function _fetchAllGroups() {
    const groups = [];
    let nextToken = undefined;
    const timer = logger.startTimer("Cognito", "Fetch all groups");
    do {
      const cmd = new ListGroupsCommand({ UserPoolId: poolId, Limit: 60, NextToken: nextToken });
      const response = await client.send(cmd);
      nextToken = response.NextToken;
      (response.Groups || []).forEach((g) => { groups.push({ name: g.GroupName, description: g.Description || "" }); });
    } while (nextToken);
    timer({ groupCount: groups.length });
    return groups;
  }

  async function _createUser(user) {
    const attributes = [];
    const addAttr = (name, value) => { if (value) attributes.push({ Name: name, Value: String(value) }); };
    addAttr(f.email, user.email);
    addAttr("email_verified", "true");
    addAttr(f.firstName, user.firstName);
    addAttr(f.lastName, user.lastName);
    addAttr(f.location, user.location);
    addAttr(f.mobile, user.mobile);
    addAttr(f.voice, user.voice);
    addAttr(f.altEmail, user.altEmail);
    addAttr(f.immutableId, user.immutableId);

    const username = emailToUsername(user.email);
    logger.debug("Cognito", "USER_CREATING", `Creating: ${user.email} (username: ${username})`, { email: user.email, username, tenantId: cfg.tenantId });
    const cmd = new AdminCreateUserCommand({
      UserPoolId: poolId, Username: username, UserAttributes: attributes,
      MessageAction: "SUPPRESS", DesiredDeliveryMediums: ["EMAIL"],
    });
    const response = await client.send(cmd);
    logger.info("Cognito", "USER_CREATED", `Created user: ${user.email}`, { email: user.email, tenantId: cfg.tenantId });

    // Link with apersona OIDC provider so user can login via Hosted UI
    try {
      await client.send(new AdminLinkProviderForUserCommand({
        Username: response.User.Username,
        UserPoolId: poolId,
        DestinationUser: {
          ProviderName: "Cognito",
          ProviderAttributeName: "email",
          ProviderAttributeValue: user.email.toLowerCase(),
        },
        SourceUser: {
          ProviderName: "apersona",
          ProviderAttributeName: "email",
          ProviderAttributeValue: user.email.toLowerCase(),
        },
      }));
      logger.debug("Cognito", "USER_LINKED", `Linked with apersona provider: ${user.email}`, { tenantId: cfg.tenantId });
    } catch (linkErr) {
      logger.error("Cognito", "USER_LINK_FAILED",
        `Failed to link ${user.email} with apersona: ${linkErr.message}`,
        { email: user.email, tenantId: cfg.tenantId, error: linkErr.message });
    }

    await sleep(30);
    return response;
  }

  async function _updateUserAttributes(user) {
    const attributes = [];
    const addAttr = (name, value) => { if (value !== undefined && value !== null) attributes.push({ Name: name, Value: String(value) }); };
    addAttr(f.firstName, user.firstName);
    addAttr(f.lastName, user.lastName);
    addAttr(f.location, user.location);
    addAttr(f.mobile, user.mobile);
    addAttr(f.voice, user.voice);
    addAttr(f.altEmail, user.altEmail);
    if (user.immutableId) addAttr(f.immutableId, user.immutableId);

    if (attributes.length === 0) {
      logger.debug("Cognito", "UPDATE_SKIP", `No attributes to update for ${user.email}`, { tenantId: cfg.tenantId });
      return;
    }
    const updateUsername = emailToUsername(user.email);
    logger.debug("Cognito", "USER_UPDATING", `Updating: ${user.email} (username: ${updateUsername})`, { email: user.email, username: updateUsername, tenantId: cfg.tenantId, attributes: attributes.map((a) => a.Name) });
    const cmd = new AdminUpdateUserAttributesCommand({ UserPoolId: poolId, Username: updateUsername, UserAttributes: attributes });
    await client.send(cmd);
    logger.info("Cognito", "USER_UPDATED", `Updated: ${user.email}`, { email: user.email, tenantId: cfg.tenantId });
    await sleep(50);
  }

  async function _batchCreateUsers(users) {
    const results = { created: [], errors: [] };
    for (const user of users) {
      try {
        await _createUser(user);
        results.created.push(user.email);
        for (const group of user.securityGroups || []) {
          try { await _addUserToGroup(user.email, group); }
          catch (groupErr) { logger.error("Cognito", "GROUP_ADD_WARN", `Could not add ${user.email} to ${group}`, { email: user.email, group, error: groupErr.message }); }
        }
      } catch (err) {
        if (err.name === "UsernameExistsException") {
          try { await _updateUserAttributes(user); results.created.push(user.email); }
          catch (updateErr) { results.errors.push({ email: user.email, error: updateErr.message }); }
        } else {
          logger.error("Cognito", "USER_CREATE_FAILED", `Failed to create ${user.email}: ${err.message}`, { email: user.email, error: err.message });
          results.errors.push({ email: user.email, error: err.message });
        }
      }
    }
    return results;
  }

  async function _batchUpdateUserAttributes(users) {
    const results = { updated: [], errors: [] };
    for (const user of users) {
      try {
        await _updateUserAttributes(user);
        results.updated.push(user.email);
        for (const group of user.securityGroups || []) {
          try { await _addUserToGroup(user.email, group); }
          catch (groupErr) { logger.error("Cognito", "GROUP_ADD_WARN", `Could not add ${user.email} to ${group}`, { email: user.email, group, error: groupErr.message }); }
        }
      } catch (err) {
        logger.error("Cognito", "USER_UPDATE_FAILED", `Failed to update ${user.email}: ${err.message}`, { email: user.email, error: err.message });
        results.errors.push({ email: user.email, error: err.message });
      }
    }
    return results;
  }

  async function _createGroup(groupName, description) {
    try {
      const cmd = new CreateGroupCommand({ UserPoolId: poolId, GroupName: groupName, Description: description || `Synced from AD: ${groupName}` });
      await client.send(cmd);
      logger.info("Cognito", "GROUP_CREATED", `Created group: ${groupName}`, { groupName, tenantId: cfg.tenantId });
    } catch (err) {
      if (err.name === "GroupExistsException") return;
      throw err;
    }
  }

  async function _addUserToGroup(username, groupName) {
    await _createGroup(groupName);
    const cmd = new AdminAddUserToGroupCommand({ UserPoolId: poolId, Username: username, GroupName: groupName });
    await client.send(cmd);
    logger.debug("Cognito", "GROUP_MEMBER_ADDED", `Added ${username} to ${groupName}`, { username, groupName, tenantId: cfg.tenantId });
    await sleep(30);
  }

  return {
    cognitoClient: client,
    adminGetUser: _adminGetUser,
    fetchUsersByRange: _fetchUsersByRange,
    fetchUserGroups: _fetchUserGroups,
    fetchAllGroups: _fetchAllGroups,
    createUser: _createUser,
    batchCreateUsers: _batchCreateUsers,
    updateUserAttributes: _updateUserAttributes,
    batchUpdateUserAttributes: _batchUpdateUserAttributes,
    createGroup: _createGroup,
    addUserToGroup: _addUserToGroup,
    sleep,
  };
}

module.exports = {
  cognitoClient, fetchUsersByRange, fetchUserGroups, fetchAllGroups,
  createUser, batchCreateUsers, updateUserAttributes, batchUpdateUserAttributes,
  createGroup, addUserToGroup, sleep,
  createCognitoUtils,
};
