/**
 * providers/generic-ldap-provider.js
 * ====================================
 * Generic LDAP provider for non-AD directory servers.
 *
 * Extends LdapBaseProvider with standard LDAP behaviour:
 *
 *   • entryUUID (string, RFC 4530) as the unique identifier
 *   • ImmutableID = entryUUID (no binary conversion needed)
 *   • objectClass=inetOrgPerson for user objects (RFC 2798)
 *   • mail as the default email attribute
 *   • uid for login/sAMAccountName equivalent
 *   • userPassword with SSHA encoding for password creation
 *   • groupOfNames / groupOfUniqueNames for group membership
 *   • member / uniqueMember for adding users to groups
 *   • modifyTimestamp (RFC 4512) for delta sync
 *
 * COMPATIBLE WITH:
 *   - OpenLDAP
 *   - 389 Directory Server (Red Hat / Fedora)
 *   - FreeIPA (uses 389DS underneath)
 *   - Apache Directory Server
 *   - Oracle Internet Directory
 *   - Any RFC 4510-compliant LDAP server
 *
 * CONFIGURATION:
 *   Set LDAP_PROVIDER=generic and configure these additional env vars:
 *
 *   LDAP_USER_OBJECT_CLASS     – Object class for users (default: inetOrgPerson)
 *   LDAP_GROUP_OBJECT_CLASS    – Object class for groups (default: groupOfNames)
 *   LDAP_GROUP_MEMBER_ATTR     – Attribute for group membership (default: member)
 *   LDAP_UNIQUE_ID_ATTR        – Unique ID attribute (default: entryUUID)
 *   LDAP_TIMESTAMP_ATTR        – Last-modified attribute (default: modifyTimestamp)
 *   LDAP_GROUP_BASE_DN         – Where to search for groups
 *
 * NOTES:
 *   - Some LDAP servers (e.g. OpenLDAP) require the memberOf overlay
 *     to be enabled for reverse group lookups. If memberOf is not
 *     available, this provider searches groups directly for membership.
 *   - entryUUID is an operational attribute in most servers; we
 *     request it explicitly with '+' or by name.
 *   - Password creation uses SSHA by default, but some servers
 *     accept plain text if configured for server-side hashing.
 */

"use strict";

const ldap = require("ldapjs");
const crypto = require("crypto");
const LdapBaseProvider = require("./ldap-base");
const logger = require("../logger");

class GenericLdapProvider extends LdapBaseProvider {
  /**
   * @param {Object} [config] - Optional config override for multi-tenant use.
   */
  constructor(config) {
    super(config);
  }

  getProviderName() {
    return "LDAP";
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Unique ID / Timestamp Helpers
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Parse modifyTimestamp (Generalized Time, RFC 4517).
   *
   * Standard format: "YYYYMMDDHHmmssZ" or "YYYYMMDDHHmmss.fracZ"
   * This is the same format as AD's whenChanged, so the same parser works.
   *
   * @param {string} timestamp
   * @returns {string|null} ISO 8601 string or null
   */
  parseTimestamp(timestamp) {
    if (!timestamp || typeof timestamp !== "string") return null;
    const m = timestamp.match(/^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})/);
    if (!m) return null;
    const date = new Date(`${m[1]}-${m[2]}-${m[3]}T${m[4]}:${m[5]}:${m[6]}Z`);
    return isNaN(date.getTime()) ? null : date.toISOString();
  }

  // ─────────────────────────────────────────────────────────────────────────
  // User Search
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Fetch users in the given alphabetical range.
   *
   * Generic LDAP: uses inetOrgPerson, mail, entryUUID, modifyTimestamp.
   * Group membership is resolved by searching groups (not memberOf).
   *
   * @param {string} startChar
   * @param {string} endChar
   * @returns {Promise<Array<Object>>} Normalised users sorted by email
   */
  async fetchUsersByRange(startChar, endChar) {
    const f = this._config.ldap.fields;
    const gf = this._config.ldap.generic;
    const timer = logger.startTimer("LDAP", `Fetch users [${startChar}-${endChar}]`);

    // Standard LDAP user filter
    const alphaFilter = this.buildAlphaRangeFilter(f.email, startChar, endChar);
    const filterStr = `(&(objectClass=${gf.userObjectClass})(${f.email}=*)${alphaFilter})`;
    logger.debug("LDAP", "SEARCH_FILTER", `Filter: ${filterStr}`);

    const attributes = [
      f.email, f.firstName, f.lastName, f.location, f.mobile, f.voice,
      f.altEmail, gf.uniqueIdAttr, gf.timestampAttr, "dn",
    ];

    // Also request operational attributes (entryUUID, modifyTimestamp)
    // Some servers need '+' to return operational attrs; ldapjs handles this
    // by including the explicit attribute names.

    const entries = await this.pagedSearch(this._config.ldap.baseDN, filterStr, attributes);

    // Pre-fetch all group memberships (since we can't rely on memberOf)
    const groupMembershipMap = await this._buildGroupMembershipMap();

    const users = [];

    for (const entry of entries) {
      const attrs = {};
      entry.attributes.forEach((attr) => {
        if (attr.type === f.altEmail) {
          // Alt email may be multi-valued in some schemas
          attrs[attr.type] = attr.values || [];
        } else {
          attrs[attr.type] = attr.values?.[0] ?? "";
        }
      });

      const email = (attrs[f.email] || "").toLowerCase().trim();
      if (!email) continue;

      // entryUUID is a string in generic LDAP (no binary conversion needed)
      const uniqueId = attrs[gf.uniqueIdAttr] || "";

      // Get the DN from the entry itself
      const dn = entry.objectName?.toString() || entry.dn?.toString() || "";

      // Look up group membership from our pre-built map
      const memberGroups = groupMembershipMap.get(dn.toLowerCase()) || [];

      const user = {
        email,
        firstName: attrs[f.firstName] || "",
        lastName: attrs[f.lastName] || "",
        location: attrs[f.location] || "",
        mobile: attrs[f.mobile] || "",
        voice: attrs[f.voice] || "",
        altEmail: Array.isArray(attrs[f.altEmail])
          ? attrs[f.altEmail].join(";")
          : attrs[f.altEmail] || "",
        uniqueId,
        immutableId: uniqueId, // For generic LDAP, immutableId = entryUUID as-is
        securityGroups: memberGroups,
        dn,
        whenChanged: this.parseTimestamp(attrs[gf.timestampAttr]),
      };

      logger.debug("LDAP", "USER_FOUND", `Found: ${email}`, {
        email, uniqueId, whenChanged: user.whenChanged,
        groups: user.securityGroups.length,
      });

      users.push(user);
    }

    users.sort((a, b) => a.email.localeCompare(b.email));
    timer({ userCount: users.length });
    return users;
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Group Search & Membership
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Fetch all groups from the directory.
   *
   * Generic LDAP: searches for groupOfNames or groupOfUniqueNames
   * (configurable via LDAP_GROUP_OBJECT_CLASS).
   *
   * @returns {Promise<Array<{name: string, dn: string}>>}
   */
  async fetchSecurityGroups() {
    const gf = this._config.ldap.generic;
    const timer = logger.startTimer("LDAP", "Fetch groups");

    const filterStr = `(objectClass=${gf.groupObjectClass})`;

    const entries = await this.pagedSearch(
      this._config.ldap.groupBaseDN, filterStr, ["cn", "dn"], 500
    );

    const groups = entries
      .map((entry) => {
        const cn = entry.attributes.find((a) => a.type === "cn")?.values?.[0] || "";
        const dn = entry.objectName?.toString() || entry.dn?.toString() || "";
        return cn ? { name: cn, dn } : null;
      })
      .filter(Boolean);

    groups.forEach((g) => logger.debug("LDAP", "GROUP_FOUND", `Found group: ${g.name}`));
    timer({ groupCount: groups.length });
    return groups;
  }

  /**
   * Build a map of DN → [group names] by reading all groups and their
   * member/uniqueMember attributes.
   *
   * This is used instead of relying on the memberOf overlay, which may
   * not be available on all LDAP servers.
   *
   * @returns {Promise<Map<string, string[]>>} Map of lowercase user DN → group name array
   * @private
   */
  async _buildGroupMembershipMap() {
    const gf = this._config.ldap.generic;
    const timer = logger.startTimer("LDAP", "Build group membership map");

    const filterStr = `(objectClass=${gf.groupObjectClass})`;
    const entries = await this.pagedSearch(
      this._config.ldap.groupBaseDN, filterStr,
      ["cn", gf.groupMemberAttr], 500
    );

    /** @type {Map<string, string[]>} */
    const membershipMap = new Map();

    for (const entry of entries) {
      const cn = entry.attributes.find((a) => a.type === "cn")?.values?.[0] || "";
      const members = entry.attributes.find((a) => a.type === gf.groupMemberAttr)?.values || [];

      for (const memberDn of members) {
        const key = memberDn.toLowerCase();
        if (!membershipMap.has(key)) membershipMap.set(key, []);
        if (cn) membershipMap.get(key).push(cn);
      }
    }

    timer({ groupsScanned: entries.length, membershipsFound: membershipMap.size });
    return membershipMap;
  }

  /**
   * Fetch group names for a single user DN (targeted query).
   *
   * Instead of scanning all groups and building a full membership map,
   * this searches for groups where the member attribute contains the
   * given user DN. Much faster for single-user lookups on large directories.
   *
   * @param {string} userDn - Distinguished name of the user
   * @returns {Promise<string[]>} Array of group common names
   * @private
   */
  async _fetchGroupsForUserDn(userDn) {
    const gf = this._config.ldap.generic;

    const filterStr = `(&(objectClass=${gf.groupObjectClass})(${gf.groupMemberAttr}=${userDn}))`;

    const entries = await this.pagedSearch(
      this._config.ldap.groupBaseDN, filterStr, ["cn"], 500
    );

    const groups = entries
      .map((entry) => entry.attributes.find((a) => a.type === "cn")?.values?.[0] || "")
      .filter(Boolean);

    logger.debug("LDAP", "USER_GROUPS_FOUND",
      `Found ${groups.length} groups for ${userDn}`, { userDn, groups });

    return groups;
  }

  // ─────────────────────────────────────────────────────────────────────────
  // User Creation
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Create a user in generic LDAP.
   *
   * Uses inetOrgPerson object class and SSHA password hashing.
   *
   * @param {Object} user
   * @returns {Promise<Object>} Created user with uniqueId
   */
  async createUser(user) {
    const client = await this.getClient();
    const f = this._config.ldap.fields;
    const gf = this._config.ldap.generic;

    // Build DN: use uid=email-prefix or cn=Full Name depending on convention
    const uid = user.email.split("@")[0];
    const cn = `${user.firstName} ${user.lastName}`.trim() || uid;
    const dn = `uid=${uid},${this._config.ldap.baseDN}`;

    const tempPassword = this._generatePassword();

    const attributes = {
      objectClass: ["top", "person", "organizationalPerson", "inetOrgPerson"],
      cn,
      uid,
      [f.email]: user.email,
      [f.firstName]: user.firstName || uid,
      [f.lastName]: user.lastName || uid,
      displayName: cn,
      userPassword: this._hashPassword(tempPassword),
    };

    if (user.location) attributes[f.location] = user.location;
    if (user.mobile) attributes[f.mobile] = user.mobile;
    if (user.voice) attributes[f.voice] = user.voice;

    logger.debug("LDAP", "USER_CREATING", `Creating: ${user.email}`, { dn });

    await new Promise((resolve, reject) => {
      client.add(dn, attributes, (err) => {
        if (err) {
          logger.error("LDAP", "USER_CREATE_FAILED",
            `Failed to create ${user.email}: ${err.message}`,
            { email: user.email, dn, errorCode: err.code }
          );
          return reject(new Error(`Failed to create LDAP user ${user.email}: ${err.message}`));
        }
        resolve();
      });
    });

    logger.info("LDAP", "USER_CREATED", `Created user: ${user.email}`, { email: user.email, dn });
    return await this.readUserByEmail(user.email);
  }

  /**
   * Read a single user by email.
   *
   * @param {string} email
   * @returns {Promise<Object|null>}
   */
  async readUserByEmail(email) {
    const f = this._config.ldap.fields;
    const gf = this._config.ldap.generic;
    logger.debug("LDAP", "USER_READ", `Reading: ${email}`);

    const filterStr = `(&(objectClass=${gf.userObjectClass})(${f.email}=${email}))`;
    const attributes = [
      f.email, f.firstName, f.lastName, f.location, f.mobile, f.voice,
      gf.uniqueIdAttr, gf.timestampAttr,
    ];

    const entries = await this.pagedSearch(this._config.ldap.baseDN, filterStr, attributes, 10);
    if (entries.length === 0) return null;

    const entry = entries[0];
    const attrs = {};
    entry.attributes.forEach((attr) => {
      attrs[attr.type] = attr.values?.[0] ?? "";
    });

    const dn = entry.objectName?.toString() || entry.dn?.toString() || "";
    const uniqueId = attrs[gf.uniqueIdAttr] || "";

    // Targeted group lookup for this user (avoids full _buildGroupMembershipMap scan)
    const memberGroups = await this._fetchGroupsForUserDn(dn);

    return {
      email: (attrs[f.email] || "").toLowerCase().trim(),
      firstName: attrs[f.firstName] || "",
      lastName: attrs[f.lastName] || "",
      location: attrs[f.location] || "",
      mobile: attrs[f.mobile] || "",
      voice: attrs[f.voice] || "",
      uniqueId,
      immutableId: uniqueId,
      securityGroups: memberGroups,
      dn,
      whenChanged: this.parseTimestamp(attrs[gf.timestampAttr]),
    };
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Group Creation & Membership
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Create a group in generic LDAP.
   *
   * groupOfNames requires at least one member, so we add a placeholder
   * (the bind DN) as the initial member. Some servers (389DS) don't
   * require this — the placeholder is harmless either way.
   *
   * @param {string} groupName
   * @returns {Promise<string>} DN
   */
  async createSecurityGroup(groupName) {
    const client = await this.getClient();
    const gf = this._config.ldap.generic;

    const dn = `cn=${groupName},${this._config.ldap.groupBaseDN}`;

    logger.debug("LDAP", "GROUP_CREATING", `Creating group: ${groupName}`, { dn });

    const attributes = {
      objectClass: ["top", gf.groupObjectClass],
      cn: groupName,
      description: `Synced from Cognito: ${groupName}`,
    };

    // groupOfNames requires at least one member on creation
    if (gf.groupObjectClass === "groupOfNames") {
      attributes.member = this._config.ldap.bindDN; // Placeholder
    } else if (gf.groupObjectClass === "groupOfUniqueNames") {
      attributes.uniqueMember = this._config.ldap.bindDN;
    }

    await new Promise((resolve, reject) => {
      client.add(dn, attributes, (err) => {
        if (err) {
          logger.error("LDAP", "GROUP_CREATE_FAILED",
            `Failed: ${groupName}: ${err.message}`, { groupName, dn });
          return reject(new Error(`Failed to create LDAP group '${groupName}': ${err.message}`));
        }
        resolve();
      });
    });

    logger.info("LDAP", "GROUP_CREATED", `Created group: ${groupName}`, { groupName, dn });
    return dn;
  }

  /**
   * Add a user to a group.
   *
   * Uses the configured group member attribute (member or uniqueMember).
   *
   * @param {string} userDn
   * @param {string} groupDn
   */
  async addUserToGroup(userDn, groupDn) {
    const client = await this.getClient();
    const gf = this._config.ldap.generic;

    const change = new ldap.Change({
      operation: "add",
      modification: new ldap.Attribute({
        type: gf.groupMemberAttr,
        values: [userDn],
      }),
    });

    await new Promise((resolve, reject) => {
      client.modify(groupDn, change, (err) => {
        // Error 20 = attribute already exists (already a member)
        // Error 68 = entry already exists
        if (err && err.code !== 20 && err.code !== 68) {
          logger.error("LDAP", "GROUP_ADD_FAILED",
            `Failed to add user to group`,
            { userDn, groupDn, error: err.message });
          return reject(new Error(`Failed to add ${userDn} to ${groupDn}: ${err.message}`));
        }
        logger.debug("LDAP", "GROUP_MEMBER_ADDED", `Added to group`, { userDn, groupDn });
        resolve();
      });
    });
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Utility (private)
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Generate a random complex password.
   * @returns {string}
   */
  _generatePassword() {
    const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*";
    let pw = "";
    for (let i = 0; i < 16; i++) pw += chars[crypto.randomInt(chars.length)];
    return pw;
  }

  /**
   * Hash a password using SSHA (Salted SHA-1).
   *
   * Format: {SSHA}base64(SHA1(password + salt) + salt)
   *
   * Most LDAP servers accept this format. Some newer servers prefer
   * PBKDF2 or argon2, but SSHA is universally supported.
   *
   * @param {string} password
   * @returns {string} SSHA-hashed password string
   */
  _hashPassword(password) {
    const salt = crypto.randomBytes(16);
    const hash = crypto.createHash("sha1");
    hash.update(password);
    hash.update(salt);
    const digest = hash.digest();
    const combined = Buffer.concat([digest, salt]);
    return `{SSHA}${combined.toString("base64")}`;
  }
}

module.exports = GenericLdapProvider;
