/**
 * config.js
 * =========
 * Central configuration for the LDAP ↔ Cognito two-way sync.
 *
 * All values can be overridden via environment variables (recommended for Lambda)
 * or by editing the defaults below for local development.
 *
 * ENVIRONMENT VARIABLES
 * ---------------------
 *
 *   ─── Provider Selection ───────────────────────────────────────────
 *   LDAP_PROVIDER           – "ad" (Active Directory, default) or "generic" (OpenLDAP, 389DS, etc.)
 *
 *   ─── LDAP Connection (all providers) ──────────────────────────────
 *   LDAP_URL                – LDAPS URL (e.g. ldaps://ad.example.com:636)
 *   LDAP_BASE_DN            – Base DN for user searches (e.g. CN=Users,DC=example,DC=com)
 *   LDAP_PORT               – LDAP(S) port (default 636)
 *   LDAP_BIND_DN            – Bind account (e.g. svc-sync@example.com or cn=admin,dc=example,dc=com)
 *   LDAP_BIND_PASSWORD      – Bind account password
 *   LDAP_TLS_REJECT_UNAUTH  – Reject untrusted TLS certs (default: true)
 *   LDAP_GROUP_BASE_DN      – Base DN for group searches (auto-derived if not set)
 *
 *   ─── LDAP Field Mappings (all providers) ──────────────────────────
 *   LDAP_FIELD_EMAIL        – Email attribute (default: "userPrincipalName" for AD, "mail" for generic)
 *   LDAP_FIELD_FIRST_NAME   – First name attr (default: "givenName")
 *   LDAP_FIELD_LAST_NAME    – Last name attr (default: "sn")
 *   LDAP_FIELD_LOCATION     – Location attr (default: "l")
 *   LDAP_FIELD_MOBILE       – Mobile phone attr (default: "mobile")
 *   LDAP_FIELD_VOICE        – Voice phone attr (default: "telephoneNumber")
 *   LDAP_FIELD_ALT_EMAIL    – Alt-email attr (default: "proxyAddresses" for AD, "mailAlternate" for generic)
 *
 *   ─── Generic LDAP Settings (only when LDAP_PROVIDER=generic) ──────
 *   LDAP_USER_OBJECT_CLASS  – User object class (default: "inetOrgPerson")
 *   LDAP_GROUP_OBJECT_CLASS – Group object class (default: "groupOfNames")
 *   LDAP_GROUP_MEMBER_ATTR  – Group membership attribute (default: "member")
 *   LDAP_UNIQUE_ID_ATTR     – Unique ID attribute (default: "entryUUID")
 *   LDAP_TIMESTAMP_ATTR     – Last-modified attribute (default: "modifyTimestamp")
 *
 *   ─── Cognito ──────────────────────────────────────────────────────
 *   COGNITO_USER_POOL_ID         – AWS Cognito User Pool ID
 *   COGNITO_FIELD_FIRST_NAME     – (default: given_name)
 *   COGNITO_FIELD_LAST_NAME      – (default: family_name)
 *   COGNITO_FIELD_LOCATION       – (default: locale)
 *   COGNITO_FIELD_MOBILE         – (default: phone_number)
 *   COGNITO_FIELD_VOICE          – (default: custom:voice-number)
 *   COGNITO_FIELD_ALT_EMAIL      – (default: custom:alter-email)
 *   COGNITO_FIELD_IMMUTABLE_ID   – (default: custom:immutableId)
 *
 *   ─── Sync Behaviour ──────────────────────────────────────────────
 *   SYNC_BATCH_SIZE          – (default: 5000)
 *   SYNC_S3_BUCKET           – S3 bucket for state files (default: ad-cognito-sync-state)
 *   SYNC_S3_STATE_KEY        – S3 key for pagination state (default: sync-state.json)
 *   SYNC_MAX_LAMBDA_MS       – Max ms before checkpoint (default: 780000 = 13 min)
 *
 *   ─── Delta Sync ──────────────────────────────────────────────────
 *   DELTA_SYNC_ENABLED       – Enable delta sync (default: true)
 *   DELTA_SYNC_S3_KEY        – S3 key for timestamps (default: delta-timestamps.json)
 *
 *   ─── Logging ─────────────────────────────────────────────────────
 *   LOG_LEVEL                – ERROR | NORMAL | DEBUG (default: NORMAL)
 */

"use strict";

const provider = (process.env.LDAP_PROVIDER || "ad").toLowerCase();
const isAD = provider === "ad";

const config = {
  // ─── LDAP Directory (unified for both providers) ───────────────────────────
  ldap: {
    provider,  // "ad" or "generic"

    // Connection settings
    url: process.env.LDAP_URL || process.env.AD_URL || "ldaps://ad.example.com:636",
    baseDN: process.env.LDAP_BASE_DN || process.env.AD_BASE_DN || "CN=Users,DC=example,DC=com",
    port: parseInt(process.env.LDAP_PORT || process.env.AD_PORT || "636", 10),
    bindDN: process.env.LDAP_BIND_DN || process.env.AD_BIND_DN || "svc-sync@example.com",
    bindPassword: process.env.LDAP_BIND_PASSWORD || process.env.AD_BIND_PASSWORD || "",

    tlsOptions: {
      rejectUnauthorized: (process.env.LDAP_TLS_REJECT_UNAUTH || process.env.AD_TLS_REJECT_UNAUTH) !== "false",
    },

    groupBaseDN: process.env.LDAP_GROUP_BASE_DN || process.env.AD_GROUP_BASE_DN || "",

    // Field mappings (defaults differ by provider)
    fields: {
      email:     process.env.LDAP_FIELD_EMAIL      || process.env.AD_FIELD_EMAIL      || (isAD ? "userPrincipalName" : "mail"),
      firstName: process.env.LDAP_FIELD_FIRST_NAME  || process.env.AD_FIELD_FIRST_NAME || "givenName",
      lastName:  process.env.LDAP_FIELD_LAST_NAME   || process.env.AD_FIELD_LAST_NAME  || "sn",
      location:  process.env.LDAP_FIELD_LOCATION    || process.env.AD_FIELD_LOCATION   || "l",
      mobile:    process.env.LDAP_FIELD_MOBILE      || process.env.AD_FIELD_MOBILE     || "mobile",
      voice:     process.env.LDAP_FIELD_VOICE       || process.env.AD_FIELD_VOICE      || "telephoneNumber",
      altEmail:  process.env.LDAP_FIELD_ALT_EMAIL   || process.env.AD_FIELD_ALT_EMAIL  || (isAD ? "proxyAddresses" : "mailAlternateAddress"),
    },

    // Generic LDAP-specific settings (ignored when provider=ad)
    generic: {
      userObjectClass:  process.env.LDAP_USER_OBJECT_CLASS  || "inetOrgPerson",
      groupObjectClass: process.env.LDAP_GROUP_OBJECT_CLASS || "groupOfNames",
      groupMemberAttr:  process.env.LDAP_GROUP_MEMBER_ATTR  || "member",
      uniqueIdAttr:     process.env.LDAP_UNIQUE_ID_ATTR     || "entryUUID",
      timestampAttr:    process.env.LDAP_TIMESTAMP_ATTR     || "modifyTimestamp",
    },
  },

  // ─── AWS Cognito ───────────────────────────────────────────────────────────
  cognito: {
    userPoolId: process.env.COGNITO_USER_POOL_ID || "",

    fields: {
      email:       "email",
      firstName:   process.env.COGNITO_FIELD_FIRST_NAME     || "given_name",
      lastName:    process.env.COGNITO_FIELD_LAST_NAME      || "family_name",
      location:    process.env.COGNITO_FIELD_LOCATION       || "locale",
      mobile:      process.env.COGNITO_FIELD_MOBILE         || "phone_number",
      voice:       process.env.COGNITO_FIELD_VOICE          || "custom:voice-number",
      altEmail:    process.env.COGNITO_FIELD_ALT_EMAIL      || "custom:alter-email",
      immutableId: process.env.COGNITO_FIELD_IMMUTABLE_ID   || "custom:immutableId",
      name:        "name",
      middleName:  "middle_name",
      nickname:    "nickname",
      birthdate:   "birthdate",
      picture:     "picture",
      profile:     "profile",
      gender:      "gender",
    },
  },

  // ─── Sync Behaviour ───────────────────────────────────────────────────────
  sync: {
    batchSize: parseInt(process.env.SYNC_BATCH_SIZE || "5000", 10),
    s3Bucket:  process.env.SYNC_S3_BUCKET    || "ad-cognito-sync-state",
    s3StateKey: process.env.SYNC_S3_STATE_KEY || "sync-state.json",
    maxLambdaMs: parseInt(process.env.SYNC_MAX_LAMBDA_MS || "780000", 10),
  },

  // ─── Delta Sync ────────────────────────────────────────────────────────────
  delta: {
    enabled: process.env.DELTA_SYNC_ENABLED !== "false",
    s3Key:   process.env.DELTA_SYNC_S3_KEY  || "delta-timestamps.json",
  },

  // ─── Logging ───────────────────────────────────────────────────────────────
  logging: {
    level: (process.env.LOG_LEVEL || "NORMAL").toUpperCase(),
  },
};

// Auto-derive group base DN if not explicitly set
if (!config.ldap.groupBaseDN) {
  // For AD: strip leading CN=Users, to get domain root
  // For generic: use the same base DN
  config.ldap.groupBaseDN = isAD
    ? config.ldap.baseDN.replace(/^CN=Users,/i, "")
    : config.ldap.baseDN;
}

/**
 * Build a config object from explicit overrides (for multi-tenant use).
 *
 * Instead of reading process.env, this constructs a full config from
 * the provided values. Used by the multi-tenant Lambda wrappers that
 * load per-tenant settings from DynamoDB/Secrets Manager.
 *
 * @param {Object} o - Override values
 * @returns {Object} Config object with the same shape as the module-level singleton
 */
function buildConfig(o = {}) {
  const prov = (o.ldapProvider || "ad").toLowerCase();
  const ad = prov === "ad";

  const ldapFields = o.fieldMappings || {};

  const sanitizeFieldName = (name) => {
    if (!name) return name;
    return name.replace(/[*()\\\0\x00]/g, "");
  };

  const resolveAdField = (cognitoAttr, fallback) => {
    const mapping = ldapFields[cognitoAttr];
    if (mapping && mapping.adField) return sanitizeFieldName(mapping.adField);
    return fallback;
  };

  const built = {
    ldap: {
      provider: prov,
      url:          o.ldapUrl       || "",
      baseDN:       o.ldapBaseDN    || "",
      port:         parseInt(o.ldapPort || "636", 10),
      bindDN:       o.ldapBindDN    || "",
      bindPassword: o.ldapBindPassword || "",
      tlsOptions:   { rejectUnauthorized: o.ldapTlsRejectUnauth !== false },
      groupBaseDN:  o.ldapGroupBaseDN || "",
      fields: {
        email:     resolveAdField("email",              ad ? "userPrincipalName" : "mail"),
        firstName: resolveAdField("given_name",         "givenName"),
        lastName:  resolveAdField("family_name",        "sn"),
        location:  resolveAdField("locale",             "l"),
        mobile:    resolveAdField("phone_number",       "mobile"),
        voice:     resolveAdField("custom:voice-number","telephoneNumber"),
        altEmail:  resolveAdField("custom:alter-email", ad ? "proxyAddresses" : "mailAlternateAddress"),
        name:      resolveAdField("name",               "givenName"),
        middleName:resolveAdField("middle_name",        null),
        nickname:  resolveAdField("nickname",           ad ? "cn" : "cn"),
        birthdate: resolveAdField("birthdate",          null),
        picture:   resolveAdField("picture",            null),
        profile:   resolveAdField("profile",            null),
        gender:    resolveAdField("gender",             null),
      },
      generic: {
        userObjectClass:  o.ldapUserObjectClass  || "inetOrgPerson",
        groupObjectClass: o.ldapGroupObjectClass || "groupOfNames",
        groupMemberAttr:  o.ldapGroupMemberAttr  || "member",
        uniqueIdAttr:     o.ldapUniqueIdAttr     || "entryUUID",
        timestampAttr:    o.ldapTimestampAttr    || "modifyTimestamp",
      },
    },
    cognito: {
      userPoolId: o.cognitoUserPoolId || "",
      fields: {
        email:       "email",
        firstName:   "given_name",
        lastName:    "family_name",
        location:    "locale",
        mobile:      "phone_number",
        voice:       "custom:voice-number",
        altEmail:    "custom:alter-email",
        immutableId: "custom:immutableId",
        name:        "name",
        middleName:  "middle_name",
        nickname:    "nickname",
        birthdate:   "birthdate",
        picture:     "picture",
        profile:     "profile",
        gender:      "gender",
      },
    },
    sync: {
      batchSize:   parseInt(o.syncBatchSize || "5000", 10),
      s3Bucket:    o.syncS3Bucket || "ad-cognito-sync-state",
      s3StateKey:  o.tenantId ? `${o.tenantId}/sync-state.json` : "sync-state.json",
      maxLambdaMs: parseInt(o.syncMaxLambdaMs || "780000", 10),
    },
    delta: {
      enabled: o.deltaSyncEnabled !== false,
      s3Key:   o.tenantId ? `${o.tenantId}/delta-timestamps.json` : "delta-timestamps.json",
    },
    logging: {
      level: (o.logLevel || "DEBUG").toUpperCase(),
    },
    tenantId:      o.tenantId || null,
    fieldMappings: o.fieldMappings || {},
  };

  if (!built.ldap.groupBaseDN) {
    built.ldap.groupBaseDN = ad
      ? built.ldap.baseDN.replace(/^CN=Users,/i, "")
      : built.ldap.baseDN;
  }

  return built;
}

module.exports = config;
module.exports.buildConfig = buildConfig;
