/**
 * providers/ad-provider.js
 * =========================
 * Active Directory provider for the two-way sync.
 *
 * Extends LdapBaseProvider with AD-specific behaviour:
 *
 *   • objectGUID (binary, little-endian) → canonical GUID → base64 ImmutableID
 *   • objectCategory=person + objectClass=user search filters
 *   • userPrincipalName as the default email attribute
 *   • sAMAccountName required for user creation
 *   • unicodePwd (quoted UTF-16LE) for password encoding
 *   • userAccountControl=512 for account activation
 *   • memberOf (native multi-valued attribute) for group membership
 *   • groupType with bitwise OID (1.2.840.113556.1.4.803) for security groups
 *   • whenChanged (Generalized Time: "YYYYMMDDHHmmss.0Z") for delta sync
 *   • proxyAddresses (SMTP:-prefixed multi-valued) for alt-email
 *
 * WHEN TO USE:
 *   Set LDAP_PROVIDER=ad (this is the default) when syncing with:
 *   - Windows Server Active Directory
 *   - Azure AD Domain Services (managed AD)
 *   - Samba AD DC (Samba 4+ in AD mode)
 */

"use strict";

const ldap = require("ldapjs");
const crypto = require("crypto");
const LdapBaseProvider = require("./ldap-base");
const logger = require("../logger");

class AdProvider extends LdapBaseProvider {
  /**
   * @param {Object} [config] - Optional config override for multi-tenant use.
   */
  constructor(config) {
    super(config);
  }

  getProviderName() {
    return "AD";
  }

  // ─────────────────────────────────────────────────────────────────────────
  // AD Attribute Name Normalisation
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Map of common PowerShell/GUI attribute names to their LDAP display names.
   * Users often configure field mappings using the names shown in AD Users &
   * Computers or PowerShell (e.g. "Surname"), but LDAP requires the actual
   * ldapDisplayName (e.g. "sn").
   *
   * @see https://learn.microsoft.com/en-us/windows/win32/adschema/attributes-all
   */
  static AD_ATTR_ALIASES = {
    "surname":        "sn",
    "lastname":       "sn",
    "last_name":      "sn",
    "familyname":     "sn",
    "family_name":    "sn",
    "firstname":      "givenName",
    "first_name":     "givenName",
    "given_name":     "givenName",
    "emailaddress":   "mail",
    "email":          "mail",
    "e-mail":         "mail",
    "city":           "l",
    "location":       "l",
    "mobilephone":    "mobile",
    "mobilenumber":   "mobile",
    "mobile_phone":   "mobile",
    "phone":          "telephoneNumber",
    "phonenumber":    "telephoneNumber",
    "phone_number":   "telephoneNumber",
    "officephone":    "telephoneNumber",
    "displayname":    "displayName",
    "samaccountname": "sAMAccountName",
  };

  /**
   * Normalise an AD attribute name: if it's a known alias (case-insensitive),
   * return the correct LDAP display name. Otherwise return as-is.
   *
   * @param {string} attrName
   * @returns {string}
   */
  normaliseLdapAttr(attrName) {
    if (!attrName) return attrName;
    const lower = attrName.toLowerCase();
    return AdProvider.AD_ATTR_ALIASES[lower] || attrName;
  }

  // ─────────────────────────────────────────────────────────────────────────
  // GUID / ImmutableID Helpers (AD-specific)
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Convert raw binary objectGUID buffer to canonical GUID string.
   *
   * AD stores objectGUID as 16 bytes with the first three components
   * in little-endian byte order.
   *
   * @param {Buffer} buf - 16-byte binary objectGUID
   * @returns {string} Canonical GUID (lowercase)
   */
  bufferToGuid(buf) {
    if (!Buffer.isBuffer(buf) || buf.length !== 16) return "";
    const hex = buf.toString("hex");
    const part = (...pos) => pos.map((i) => hex.substr(i, 2)).join("");
    return (
      part(6, 4, 2, 0) + "-" + part(10, 8) + "-" + part(14, 12) + "-" +
      hex.substr(16, 4) + "-" + hex.substr(20)
    ).toLowerCase();
  }

  /**
   * Convert a canonical GUID string to a base64-encoded ImmutableID.
   *
   * This matches the Azure AD / M365 convention: the GUID bytes
   * (with the first three components in little-endian order) are
   * base64-encoded to produce the ImmutableID.
   *
   * @param {string} guid - Canonical GUID string
   * @returns {string} Base64-encoded ImmutableID
   */
  guidToImmutableId(guid) {
    const hex = guid.replace(/-/g, "");
    if (hex.length !== 32) throw new Error(`Invalid GUID format: ${guid}`);

    const buf = Buffer.alloc(16);
    buf.writeUInt32LE(parseInt(hex.substring(0, 8), 16), 0);
    buf.writeUInt16LE(parseInt(hex.substring(8, 12), 16), 4);
    buf.writeUInt16LE(parseInt(hex.substring(12, 16), 16), 6);
    for (let i = 0; i < 8; i++) {
      buf[8 + i] = parseInt(hex.substring(16 + i * 2, 18 + i * 2), 16);
    }
    return buf.toString("base64");
  }

  /**
   * Parse AD's whenChanged Generalized Time into ISO 8601.
   *
   * @param {string} whenChanged - e.g. "20250213143022.0Z"
   * @returns {string|null} ISO string or null
   */
  parseTimestamp(whenChanged) {
    if (!whenChanged || typeof whenChanged !== "string") return null;
    const m = whenChanged.match(/^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})/);
    if (!m) return null;
    const date = new Date(`${m[1]}-${m[2]}-${m[3]}T${m[4]}:${m[5]}:${m[6]}Z`);
    return isNaN(date.getTime()) ? null : date.toISOString();
  }

  // ─────────────────────────────────────────────────────────────────────────
  // User Search
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Fetch AD users in the given alphabetical range.
   *
   * AD-specific: uses objectCategory=person, objectClass=user,
   * binary objectGUID, memberOf, proxyAddresses, whenChanged.
   *
   * @param {string} startChar
   * @param {string} endChar
   * @returns {Promise<Array<Object>>} Normalised users sorted by email
   */
  async fetchUsersByRange(startChar, endChar) {
    const f = this._config.ldap.fields;
    const timer = logger.startTimer("AD", `Fetch users [${startChar}-${endChar}]`);

    // Normalise email field name (e.g. "Mail" → "mail")
    const emailField = this.normaliseLdapAttr(f.email);

    // Use the same simple filter that works in get_ad_users_2.js:
    //   (&(objectCategory=person)(objectClass=user))
    // Do NOT add (userPrincipalName=*) or alpha range filters at the LDAP level —
    // some AD configurations don't support substring/existence queries on UPN.
    // Instead, we fetch ALL users and filter by email first-letter in code.
    const filterStr = `(&(objectCategory=person)(objectClass=user))`;

    // Get the bind DN to exclude the sync service account itself
    const bindDN = this._config.ldap.bindDN || "";
    const bindEmail = bindDN.includes("@") ? bindDN.toLowerCase() : "";

    logger.info("AD", "SEARCH_START", `Searching AD users [${startChar}-${endChar}]`, {
      baseDN: this._config.ldap.baseDN,
      emailField,
      configuredEmailField: f.email,
      filter: filterStr,
      alphaRange: `${startChar}-${endChar}`,
      excludeBindEmail: bindEmail || "(none)",
    });

    const attributes = [
      f.email, f.firstName, f.lastName, f.location, f.mobile, f.voice,
      f.altEmail, "objectGUID", "memberOf", "distinguishedName", "whenChanged",
      "userPrincipalName",
    ];

    const entries = await this.pagedSearch(this._config.ldap.baseDN, filterStr, attributes);
    const users = [];
    let skippedNoEmail = 0;
    let skippedServiceAccount = 0;

    for (const entry of entries) {
      const attrs = {};
      entry.attributes.forEach((attr) => {
        if (attr.type === "objectGUID") {
          // objectGUID is binary — keep the raw buffer
          attrs[attr.type] = attr.buffers?.[0] ?? null;
        } else if (attr.type === "memberOf") {
          // Multi-valued: all group DNs
          attrs[attr.type] = attr.values || [];
        } else if (attr.type === f.altEmail) {
          // proxyAddresses: extract SMTP:-prefixed addresses
          attrs[attr.type] = (attr.values || [])
            .filter((v) => v.startsWith("smtp:") || v.startsWith("SMTP:"))
            .map((v) => v.replace(/^smtp:/i, ""));
        } else {
          attrs[attr.type] = attr.values?.[0] ?? "";
        }
      });

      // Email: prefer configured field (e.g. Mail), fall back to userPrincipalName
      const upn = (attrs.userPrincipalName || "").toLowerCase().trim();
      const mailAttr = (attrs[emailField] || attrs[f.email] || "").toLowerCase().trim();
      const email = mailAttr || upn;

      if (!email) {
        skippedNoEmail++;
        continue; // Skip entries with no email at all (computer accounts, etc.)
      }

      // Skip the AD Sync service account itself
      if (bindEmail && email === bindEmail) {
        skippedServiceAccount++;
        logger.debug("AD", "SKIP_SERVICE_ACCOUNT", `Skipping sync service account: ${email}`, { email });
        continue;
      }

      // Client-side alpha range filter: only include users whose email starts
      // with a character in [startChar, endChar]. This replaces the LDAP-level
      // alpha filter which didn't work on this AD.
      const firstChar = email.charAt(0).toLowerCase();
      const startCode = startChar.toLowerCase().charCodeAt(0);
      const endCode = endChar.toLowerCase().charCodeAt(0);
      const charCode = firstChar.charCodeAt(0);
      if (charCode < startCode || charCode > endCode) {
        continue; // Not in this batch's range
      }

      const guidStr = this.bufferToGuid(attrs.objectGUID);

      const user = {
        email,
        firstName: attrs[f.firstName] || "",
        lastName: attrs[f.lastName] || "",
        location: attrs[f.location] || "",
        mobile: attrs[f.mobile] || "",
        voice: attrs[f.voice] || "",
        altEmail: Array.isArray(attrs[f.altEmail])
          ? attrs[f.altEmail].join(";")
          : attrs[f.altEmail] || "",
        uniqueId: guidStr,
        immutableId: guidStr ? this.guidToImmutableId(guidStr) : "",
        securityGroups: (attrs.memberOf || [])
          .map((dn) => this.extractGroupCN(dn))
          .filter(Boolean),
        dn: attrs.distinguishedName || "",
        whenChanged: this.parseTimestamp(attrs.whenChanged),
      };

      logger.debug("AD", "USER_FOUND", `Found: ${email}`, {
        email, upn, mailAttr: mailAttr || "(empty)",
        uniqueId: guidStr, whenChanged: user.whenChanged,
        groups: user.securityGroups.length,
      });

      users.push(user);
    }

    users.sort((a, b) => a.email.localeCompare(b.email));
    timer({ userCount: users.length, totalEntries: entries.length, skippedNoEmail, skippedServiceAccount });
    logger.info("AD", "SEARCH_COMPLETE", `[${startChar}-${endChar}] Found ${users.length} users (${entries.length} entries, skipped: ${skippedNoEmail} no-email, ${skippedServiceAccount} service-account)`, {
      userCount: users.length, totalEntries: entries.length, skippedNoEmail, skippedServiceAccount,
    });
    return users;
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Security Group Search
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Fetch all AD security groups.
   *
   * AD-specific: uses groupType bitwise filter (OID 1.2.840.113556.1.4.803)
   * with the security-enabled bit (0x80000000 = 2147483648).
   *
   * @returns {Promise<Array<{name: string, dn: string}>>}
   */
  async fetchSecurityGroups() {
    const timer = logger.startTimer("AD", "Fetch security groups");

    // AD bitwise AND filter: groupType has security bit set
    const filterStr = "(&(objectClass=group)(groupType:1.2.840.113556.1.4.803:=2147483648))";

    logger.info("AD", "GROUPS_SEARCH_START", `Searching AD security groups`, {
      groupBaseDN: this._config.ldap.groupBaseDN,
      filter: filterStr,
    });

    const entries = await this.pagedSearch(
      this._config.ldap.groupBaseDN, filterStr, ["cn", "distinguishedName"], 500
    );

    const groups = entries
      .map((entry) => {
        const attrs = {};
        entry.attributes.forEach((a) => { attrs[a.type] = a.values?.[0] ?? ""; });
        return attrs.cn ? { name: attrs.cn, dn: attrs.distinguishedName || "" } : null;
      })
      .filter(Boolean);

    logger.info("AD", "GROUPS_SEARCH_COMPLETE", `Found ${groups.length} security groups`, {
      groupCount: groups.length,
      groupNames: groups.map(g => g.name),
    });
    groups.forEach((g) => logger.debug("AD", "GROUP_FOUND", `Found group: ${g.name}`));
    timer({ groupCount: groups.length });
    return groups;
  }

  // ─────────────────────────────────────────────────────────────────────────
  // User Creation
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Create a user in Active Directory.
   *
   * AD-specific: requires sAMAccountName, unicodePwd (quoted UTF-16LE),
   * userAccountControl=512. After creation, reads the user back to
   * obtain the server-generated objectGUID.
   *
   * @param {Object} user
   * @returns {Promise<Object>} Created user with uniqueId/immutableId
   */
  async createUser(user) {
    const client = await this.getClient();
    const f = this._config.ldap.fields;

    const cn = `${user.firstName} ${user.lastName}`.trim() || user.email.split("@")[0];
    const dn = `CN=${cn},${this._config.ldap.baseDN}`;
    const tempPassword = this._generatePassword();

    // AD requires password as a quoted UTF-16LE string
    const encodedPassword = Buffer.from(`"${tempPassword}"`, "utf16le");

    // Build attributes — AD rejects empty-string values ("No Such Attribute" error),
    // so we only include attributes that have non-empty values.
    // NOTE: We use f.email (from config, e.g. "Mail") as the email attribute.
    // We do NOT also set "mail" separately — that would duplicate if f.email IS "mail"/"Mail".
    // Normalise the email field name (e.g. "Mail" stays valid for AD, but we ensure consistency)
    const emailAttr = this.normaliseLdapAttr(f.email);

    const attributes = {
      objectClass: ["top", "person", "organizationalPerson", "user"],
      cn,
      [emailAttr]: user.email,
      userPrincipalName: user.email, // AD login name (always set, even if email field differs)
      sAMAccountName: user.email.split("@")[0].substring(0, 20), // AD max 20 chars
      displayName: `${user.firstName} ${user.lastName}`.trim() || cn,
      userAccountControl: "514", // NORMAL_ACCOUNT + ACCOUNTDISABLE (create disabled, then enable after pwd set)
    };

    // Only add "mail" if emailAttr is NOT already "mail" (avoid duplicate attribute)
    if (emailAttr.toLowerCase() !== "mail") {
      attributes.mail = user.email;
    }

    // Only add optional string attributes if they have a non-empty value.
    // AD's LDAP implementation throws "No Such Attribute" for empty strings.
    // We normalise attribute names (e.g. "Surname" → "sn") because admins
    // often configure field mappings using PowerShell/GUI names rather than
    // the actual LDAP attribute names.
    if (user.firstName) attributes[this.normaliseLdapAttr(f.firstName)] = user.firstName;
    if (user.lastName) attributes[this.normaliseLdapAttr(f.lastName)] = user.lastName;
    if (user.location) attributes[this.normaliseLdapAttr(f.location)] = user.location;
    if (user.mobile) attributes[this.normaliseLdapAttr(f.mobile)] = user.mobile;
    if (user.voice) attributes[this.normaliseLdapAttr(f.voice)] = user.voice;

    logger.info("AD", "USER_CREATING", `Creating AD user: ${user.email}`, {
      dn, email: user.email,
      hasFirstName: !!user.firstName, hasLastName: !!user.lastName,
      attributeKeys: Object.keys(attributes),
    });

    // STEP 1: Create user WITHOUT password (disabled state, userAccountControl=514)
    await new Promise((resolve, reject) => {
      client.add(dn, attributes, (err) => {
        if (err) {
          logger.error("AD", "USER_CREATE_FAILED",
            `Failed to create ${user.email}: ${err.message}`,
            { email: user.email, dn, errorCode: err.code }
          );
          return reject(new Error(`Failed to create AD user ${user.email}: ${err.message}`));
        }
        resolve();
      });
    });

    logger.info("AD", "USER_CREATED_DISABLED", `Created user (disabled): ${user.email}`, { email: user.email, dn });

    // STEP 2: Try to set password (may fail if bind account lacks permission — non-fatal)
    try {
      const pwdChange = new ldap.Change({
        operation: "replace",
        modification: new ldap.Attribute({ type: "unicodePwd", buffers: [encodedPassword] }),
      });
      await new Promise((resolve, reject) => {
        client.modify(dn, pwdChange, (err) => err ? reject(err) : resolve());
      });
      logger.info("AD", "USER_PASSWORD_SET", `Password set for: ${user.email}`, { email: user.email });

      // STEP 3: Enable the account (userAccountControl=512)
      const enableChange = new ldap.Change({
        operation: "replace",
        modification: new ldap.Attribute({ type: "userAccountControl", values: ["512"] }),
      });
      await new Promise((resolve, reject) => {
        client.modify(dn, enableChange, (err) => err ? reject(err) : resolve());
      });
      logger.info("AD", "USER_ENABLED", `Account enabled: ${user.email}`, { email: user.email });
    } catch (pwdErr) {
      // Password set failed — user remains disabled but IS created in AD
      logger.error("AD", "USER_PASSWORD_FAILED",
        `Password/enable failed for ${user.email} (user created but disabled): ${pwdErr.message}`,
        { email: user.email, dn, errorCode: pwdErr.code, error: pwdErr.message }
      );
    }

    return await this.readUserByEmail(user.email);
  }

  /**
   * Read a single AD user by email (userPrincipalName).
   *
   * @param {string} email
   * @returns {Promise<Object|null>}
   */
  async readUserByEmail(email) {
    const f = this._config.ldap.fields;
    const emailField = this.normaliseLdapAttr(f.email);
    logger.debug("AD", "USER_READ", `Reading: ${email}`, { emailField });

    // Escape LDAP special characters in email to prevent filter injection
    const safeEmail = email.replace(/([\\*()\\x00])/g, "\\$1");

    // Search by configured email field OR userPrincipalName (users may only have UPN)
    const filterStr = `(&(objectClass=user)(|(${emailField}=${safeEmail})(userPrincipalName=${safeEmail})))`;
    const attributes = [
      f.email, f.firstName, f.lastName, f.location, f.mobile, f.voice,
      f.altEmail, "objectGUID", "memberOf", "distinguishedName", "whenChanged",
      "userPrincipalName",
    ];

    const entries = await this.pagedSearch(this._config.ldap.baseDN, filterStr, attributes, 10);
    if (entries.length === 0) return null;

    const entry = entries[0];
    const attrs = {};
    entry.attributes.forEach((attr) => {
      if (attr.type === "objectGUID") attrs[attr.type] = attr.buffers?.[0] ?? null;
      else if (attr.type === "memberOf") attrs[attr.type] = attr.values || [];
      else if (attr.type === f.altEmail) {
        // proxyAddresses: extract SMTP:-prefixed addresses (multi-valued)
        attrs[attr.type] = (attr.values || [])
          .filter((v) => v.startsWith("smtp:") || v.startsWith("SMTP:"))
          .map((v) => v.replace(/^smtp:/i, ""));
      }
      else attrs[attr.type] = attr.values?.[0] ?? "";
    });

    const guidStr = this.bufferToGuid(attrs.objectGUID);
    return {
      email: (attrs[f.email] || "").toLowerCase().trim(),
      firstName: attrs[f.firstName] || "",
      lastName: attrs[f.lastName] || "",
      location: attrs[f.location] || "",
      mobile: attrs[f.mobile] || "",
      voice: attrs[f.voice] || "",
      altEmail: Array.isArray(attrs[f.altEmail])
        ? attrs[f.altEmail].join(";")
        : attrs[f.altEmail] || "",
      uniqueId: guidStr,
      immutableId: guidStr ? this.guidToImmutableId(guidStr) : "",
      securityGroups: (attrs.memberOf || []).map((dn) => this.extractGroupCN(dn)).filter(Boolean),
      dn: attrs.distinguishedName || "",
      whenChanged: this.parseTimestamp(attrs.whenChanged),
    };
  }

  // ─────────────────────────────────────────────────────────────────────────
  // User Update
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Update attributes on an existing AD user via LDAP modify (replace).
   *
   * Maps logical field names to LDAP attribute names using the configured
   * field mappings + normaliseLdapAttr(). Only modifies fields that have
   * non-empty values in the changes object.
   *
   * @param {string} dn - Distinguished Name of the AD user
   * @param {Object} changes - Logical field changes: { mobile?, voice?, altEmail?, firstName?, lastName?, location? }
   * @returns {Promise<{modified: string[]}>} List of LDAP attribute names actually written
   */
  async updateUser(dn, changes) {
    const client = await this.getClient();
    const f = this._config.ldap.fields;

    // Map logical field names to LDAP attribute names
    const fieldMapping = {
      mobile: this.normaliseLdapAttr(f.mobile),
      voice: this.normaliseLdapAttr(f.voice),
      altEmail: this.normaliseLdapAttr(f.altEmail),
      firstName: this.normaliseLdapAttr(f.firstName),
      lastName: this.normaliseLdapAttr(f.lastName),
      location: this.normaliseLdapAttr(f.location),
    };

    const modifications = [];
    const modified = [];

    for (const [logicalName, value] of Object.entries(changes)) {
      if (!value || !fieldMapping[logicalName]) continue;

      const ldapAttr = fieldMapping[logicalName];

      // Skip altEmail/proxyAddresses — AD proxyAddresses is multi-valued with SMTP:
      // (primary), smtp: (secondary), X500:, SIP: etc. A blind replace would:
      //   1. Demote primary address (SMTP: → smtp:) breaking Exchange routing
      //   2. Delete non-SMTP proxy types (X500, SIP) causing data loss
      // Cognito→AD altEmail sync is handled at user creation time only.
      if (logicalName === "altEmail") {
        logger.debug("AD", "UPDATE_USER_SKIP_ALTEMAIL",
          `Skipping altEmail/proxyAddresses update (replace would cause data loss)`, { dn });
        continue;
      }

      modifications.push(new ldap.Change({
        operation: "replace",
        modification: new ldap.Attribute({ type: ldapAttr, values: [String(value)] }),
      }));
      modified.push(ldapAttr);
    }

    if (modifications.length === 0) {
      logger.debug("AD", "UPDATE_USER_SKIP", `No non-empty fields to update for DN: ${dn}`, { dn });
      return { modified: [] };
    }

    logger.info("AD", "UPDATE_USER_START", `Updating ${modifications.length} attributes for: ${dn}`, {
      dn, attributes: modified,
    });

    await new Promise((resolve, reject) => {
      client.modify(dn, modifications, (err) => {
        if (err) {
          logger.error("AD", "UPDATE_USER_FAILED", `Failed to update ${dn}: ${err.message}`, {
            dn, attributes: modified, errorCode: err.code, error: err.message,
          });
          return reject(new Error(`Failed to update AD user ${dn}: ${err.message}`));
        }
        resolve();
      });
    });

    logger.info("AD", "UPDATE_USER_SUCCESS", `Updated ${modified.length} attributes for: ${dn}`, {
      dn, attributes: modified,
    });

    return { modified };
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Security Group Creation & Membership
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Create an AD security group. Returns { dn, created } where `created`
   * is true only if a NEW group was actually created (false if it already existed).
   *
   * @param {string} groupName
   * @returns {Promise<{dn: string, created: boolean}>}
   */
  async createSecurityGroup(groupName) {
    const client = await this.getClient();
    // Use groupBaseDN directly — do NOT assume OU=Groups exists.
    // groupBaseDN is typically the domain root (e.g. DC=weaveai,DC=net)
    // or a specific OU configured by the admin.
    const dn = `CN=${groupName},CN=Users,${this._config.ldap.groupBaseDN}`;

    logger.info("AD", "GROUP_CREATING", `Creating group: ${groupName}`, { dn, groupBaseDN: this._config.ldap.groupBaseDN });

    const created = await new Promise((resolve, reject) => {
      client.add(dn, {
        objectClass: ["top", "group"],
        cn: groupName,
        sAMAccountName: groupName.replace(/\s+/g, "_").substring(0, 256),
        groupType: "-2147483646", // Global Security Group
        description: `Synced from Cognito: ${groupName}`,
      }, (err) => {
        if (err) {
          // Error code 68 = Entry Already Exists — safe to ignore for groups
          if (err.code === 68 || (err.message && err.message.includes("Entry Already Exists"))) {
            logger.info("AD", "GROUP_EXISTS", `Group already exists: ${groupName}`, { groupName, dn });
            return resolve(false); // NOT newly created
          }
          logger.error("AD", "GROUP_CREATE_FAILED",
            `Failed: ${groupName}: ${err.message}`, { groupName, dn });
          return reject(new Error(`Failed to create AD group '${groupName}': ${err.message}`));
        }
        resolve(true); // Newly created
      });
    });

    if (created) {
      logger.info("AD", "GROUP_CREATED", `Created new group: ${groupName}`, { groupName, dn });
    }
    return { dn, created };
  }

  /**
   * Add a user to an AD security group via the `member` attribute.
   *
   * @param {string} userDn
   * @param {string} groupDn
   */
  async addUserToGroup(userDn, groupDn) {
    const client = await this.getClient();
    const change = new ldap.Change({
      operation: "add",
      modification: new ldap.Attribute({ type: "member", values: [userDn] }),
    });

    await new Promise((resolve, reject) => {
      client.modify(groupDn, change, (err) => {
        // Error 68 = entry already exists (already a member) — safe to ignore
        if (err && err.code !== 68) {
          logger.error("AD", "GROUP_ADD_FAILED",
            `Failed to add user to group`,
            { userDn, groupDn, error: err.message });
          return reject(new Error(`Failed to add ${userDn} to ${groupDn}: ${err.message}`));
        }
        logger.debug("AD", "GROUP_MEMBER_ADDED", `Added to group`, { userDn, groupDn });
        resolve();
      });
    });
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Utility (private)
  // ─────────────────────────────────────────────────────────────────────────

  /**
   * Generate a random password meeting AD complexity requirements.
   * @returns {string}
   */
  _generatePassword() {
    const upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ", lower = "abcdefghijklmnopqrstuvwxyz";
    const digits = "0123456789", symbols = "!@#$%^&*()_+-=";
    const all = upper + lower + digits + symbols;
    let pw = "";
    pw += upper[crypto.randomInt(upper.length)];
    pw += lower[crypto.randomInt(lower.length)];
    pw += digits[crypto.randomInt(digits.length)];
    pw += symbols[crypto.randomInt(symbols.length)];
    for (let i = 4; i < 16; i++) pw += all[crypto.randomInt(all.length)];
    return pw.split("").sort(() => crypto.randomInt(3) - 1).join("");
  }
}

module.exports = AdProvider;
