/**
 * sync-engine.js
 * ===============
 * Core two-way synchronisation engine between Active Directory and AWS Cognito.
 *
 * ┌──────────────────────────────────────────────────────────────────────────┐
 * │                    HIGH-LEVEL SYNC FLOW                                  │
 * │                                                                          │
 * │  For each alphabetical batch (a-d, e-h, ... w-z):                       │
 * │                                                                          │
 * │  ┌─────────┐           ┌─────────────┐                                   │
 * │  │   AD    │  ──1──▶  │ Fetch users  │                                   │
 * │  └─────────┘           │ by range     │                                   │
 * │  ┌─────────┐           ┌──────▼──────┐                                   │
 * │  │ Cognito │  ──2──▶  │ Fetch users  │                                   │
 * │  └─────────┘           │ by range     │                                   │
 * │                        └──────┬──────┘                                   │
 * │                        ┌──────▼──────┐                                   │
 * │                  3 ──▶ │  COMPARE    │                                   │
 * │                        │  & DIFF     │                                   │
 * │                        └──────┬──────┘                                   │
 * │                    ┌──────────┼──────────┐                               │
 * │              ┌─────▼─────┐  ┌─▼──┐  ┌───▼────┐                          │
 * │        4 ──▶ │ Cognito   │  │Both│  │  AD    │ ◀── 5                    │
 * │              │ only →    │  │sys │  │ only → │                           │
 * │              │ create AD │  │    │  │ create │                           │
 * │              └─────┬─────┘  │ Δ  │  │Cognito │                           │
 * │                    │        │skip│  └───┬────┘                           │
 * │                    ▼        ▼    ▼      ▼                                │
 * │              ┌──────────────────────────────┐                            │
 * │        6 ──▶ │  Sync Security Groups        │                            │
 * │              └──────────────┬───────────────┘                            │
 * │                       ┌─────▼─────┐                                      │
 * │                 7 ──▶ │  SINGLE    │                                      │
 * │                       │  Cognito   │                                      │
 * │                       │  batch     │                                      │
 * │                       │  write     │                                      │
 * │                       └───────────┘                                      │
 * │                                                                          │
 * │  8 ──▶ Checkpoint & repeat for next alphabetical batch                   │
 * └──────────────────────────────────────────────────────────────────────────┘
 *
 * DELTA SYNC:
 *   When enabled (default), the engine loads the timestamp of the last
 *   completed sync from S3. For users that exist in BOTH systems, if
 *   BOTH the AD `whenChanged` AND Cognito `UserLastModifiedDate` are
 *   older than that timestamp, the user is skipped entirely — no
 *   attribute comparison, no writes. This dramatically reduces processing
 *   time and Cognito API costs for subsequent runs.
 *
 *   Users that exist in only ONE system (new users) are ALWAYS processed
 *   regardless of the delta timestamp.
 *
 * AUTHORITATIVE SOURCE RULES:
 *   • Cognito → mobile phone, voice phone, alt-email
 *   • AD → objectGUID/immutableID, first name, last name, location
 *   • Email = universal user key
 *   • Security groups → bidirectional union (additive only)
 *
 * COST OPTIMISATION:
 *   • Cognito reads happen first (cheap)
 *   • Delta skip avoids unnecessary comparisons
 *   • All changes collected into one sync file
 *   • Cognito writes happen ONCE per user per batch
 */

"use strict";

const { getProvider } = require("./providers");
const cognito = require("./cognito-utils");
const {
  ALPHA_RANGES, loadState, saveState, createInitialState, markComplete, loadDeltaTimestamp,
} = require("./sync-state");
const config = require("./config");
const logger = require("./logger");

/**
 * Domain Restriction — keep in sync with all inline implementations:
 *   - packages/admin-portal/cdk/lambda/userslist/post.mjs
 *   - packages/admin-portal/cdk/lambda/importusersworker/index.mjs
 *   - packages/service/cdk/lambda/amfa/utils/signUp.mjs
 *   - CognitoAdSync/sync-engine.js
 *
 * @param {string} email - User email address
 * @param {string[]} allowedDomains - Permitted domains (empty/null = allow all)
 * @returns {{ allowed: boolean, domain?: string, error?: string }}
 */
function validateEmailDomain(email, allowedDomains) {
  if (!allowedDomains || allowedDomains.length === 0) return { allowed: true };
  const domain = email.split('@')[1]?.toLowerCase();
  if (!domain) return { allowed: false, error: 'Invalid email format' };
  const allowed = allowedDomains.some(d => d.toLowerCase() === domain);
  if (!allowed) return { allowed: false, domain, error: 'Your login domain is not permitted.' };
  return { allowed: true, domain };
}

// ─────────────────────────────────────────────────────────────────────────────
// STEP 3: Compare and Diff
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Compare AD and Cognito user lists and produce diff sets.
 *
 * @param {Array} adUsers
 * @param {Array} cognitoUsers
 * @returns {Object} Diff with adOnly, cognitoOnly, inBoth, group sets
 */
function compareUsers(adUsers, cognitoUsers) {
  const adMap = new Map();
  adUsers.forEach((u) => adMap.set(u.email.toLowerCase(), u));

  const cognitoMap = new Map();
  cognitoUsers.forEach((u) => cognitoMap.set(u.email.toLowerCase(), u));

  const result = {
    adOnly: [],
    cognitoOnly: [],
    inBoth: [],
    allAdGroups: new Set(),
    allCognitoGroups: new Set(),
  };

  for (const [email, adUser] of adMap) {
    const cognitoUser = cognitoMap.get(email);
    if (cognitoUser) {
      result.inBoth.push({ ad: adUser, cognito: cognitoUser });
    } else {
      result.adOnly.push(adUser);
    }
    (adUser.securityGroups || []).forEach((g) => result.allAdGroups.add(g));
  }

  for (const [email, cognitoUser] of cognitoMap) {
    if (!adMap.has(email)) {
      result.cognitoOnly.push(cognitoUser);
    }
    (cognitoUser.securityGroups || []).forEach((g) => result.allCognitoGroups.add(g));
  }

  logger.info("Sync", "DIFF_RESULT", "User comparison complete", {
    adOnly: result.adOnly.length,
    cognitoOnly: result.cognitoOnly.length,
    inBoth: result.inBoth.length,
    adGroups: result.allAdGroups.size,
    cognitoGroups: result.allCognitoGroups.size,
  });

  return result;
}

// ─────────────────────────────────────────────────────────────────────────────
// DELTA SYNC: Filter unchanged users
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Filter out user pairs where BOTH sides are unchanged since the last sync.
 *
 * A user is considered "unchanged" if:
 *   1. AD's `whenChanged` is older than the last sync timestamp, AND
 *   2. Cognito's `UserLastModifiedDate` is older than the last sync timestamp
 *
 * If EITHER side has changed, the pair is kept for full comparison.
 * If either timestamp is missing/null, the pair is kept (safe default).
 *
 * @param {Array<{ad: Object, cognito: Object}>} inBothPairs
 * @param {string|null} lastSyncTimestamp - ISO 8601 from delta-timestamps.json
 * @returns {{changed: Array, skipped: number}}
 */
function filterUnchangedUsers(inBothPairs, lastSyncTimestamp) {
  // If no delta timestamp, this is the first run — process everyone
  if (!lastSyncTimestamp || !config.delta.enabled) {
    logger.info("Delta", "FULL_SYNC",
      config.delta.enabled
        ? "No prior sync timestamp — processing all shared users"
        : "Delta sync disabled — processing all shared users",
      { totalPairs: inBothPairs.length }
    );
    return { changed: inBothPairs, skipped: 0 };
  }

  const cutoff = new Date(lastSyncTimestamp);
  const changed = [];
  let skipped = 0;

  for (const pair of inBothPairs) {
    const adChanged = pair.ad.whenChanged ? new Date(pair.ad.whenChanged) : null;
    const cognitoChanged = pair.cognito.lastModified ? new Date(pair.cognito.lastModified) : null;

    // Skip only if BOTH timestamps exist AND are older than the cutoff
    if (adChanged && cognitoChanged && adChanged < cutoff && cognitoChanged < cutoff) {
      skipped++;
      logger.deltaSkip("Delta", pair.ad.email,
        `AD: ${pair.ad.whenChanged}, Cognito: ${pair.cognito.lastModified}, cutoff: ${lastSyncTimestamp}`
      );
    } else {
      // At least one side changed (or timestamp missing) — keep for processing
      changed.push(pair);

      logger.debug("Delta", "USER_CHANGED", `Will process: ${pair.ad.email}`, {
        email: pair.ad.email,
        adChanged: pair.ad.whenChanged,
        cognitoChanged: pair.cognito.lastModified,
        cutoff: lastSyncTimestamp,
      });
    }
  }

  logger.info("Delta", "FILTER_RESULT", `Delta filter: ${skipped} skipped, ${changed.length} to process`, {
    total: inBothPairs.length, changed: changed.length, skipped,
  });

  return { changed, skipped };
}

// ─────────────────────────────────────────────────────────────────────────────
// STEP 4: Cognito-only → Create in AD, queue Cognito update
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Process users that exist in Cognito but not in AD.
 *
 * For each: create in AD → read back for objectGUID → build Cognito
 * update record with new immutableId.
 *
 * @param {Array} cognitoOnlyUsers
 * @returns {Promise<Array>} Cognito sync records
 */
async function processCognitoOnlyUsers(cognitoOnlyUsers) {
  const cognitoSyncRecords = [];

  for (const user of cognitoOnlyUsers) {
    try {
      const ldap = getProvider();
      logger.debug("Sync", "COGNITO_ONLY", `Creating in LDAP: ${user.email}`, { email: user.email });

      const adUser = await ldap.createUser({
        email: user.email,
        firstName: user.firstName,
        lastName: user.lastName,
        location: user.location,
        mobile: user.mobile,
        voice: user.voice,
      });

      if (!adUser) {
        logger.error("Sync", "AD_READBACK_FAILED",
          `Created AD user but could not read back: ${user.email}`,
          { email: user.email }
        );
        continue;
      }

      // Cognito authoritative for phone/alt-email; AD provides immutableId
      cognitoSyncRecords.push({
        email: user.email,
        firstName: user.firstName,
        lastName: user.lastName,
        location: user.location,
        mobile: user.mobile,
        voice: user.voice,
        altEmail: user.altEmail,
        immutableId: adUser.immutableId,
        securityGroups: user.securityGroups || [],
        action: "update",
      });

      // Add user to AD security groups
      for (const groupName of user.securityGroups || []) {
        try {
          const adGroups = await ldap.fetchSecurityGroups();
          const group = adGroups.find((g) => g.name === groupName);
          if (group && adUser.dn) {
            await ldap.addUserToGroup(adUser.dn, group.dn);
          }
        } catch (groupErr) {
          logger.error("Sync", "AD_GROUP_ADD_WARN",
            `Could not add ${user.email} to AD group ${groupName}`,
            { email: user.email, group: groupName, error: groupErr.message }
          );
        }
      }
    } catch (err) {
      logger.error("Sync", "COGNITO_ONLY_FAILED",
        `Error processing Cognito-only user: ${user.email}: ${err.message}`,
        { email: user.email, error: err.message, stack: err.stack }
      );
    }
  }

  return cognitoSyncRecords;
}

// ─────────────────────────────────────────────────────────────────────────────
// STEP 5: AD-only → Queue for Cognito creation
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Build Cognito sync records for AD-only users. Pure data transform, no API calls.
 * Domain Restriction: if allowedDomains is provided and non-empty, users with
 * non-permitted email domains are skipped (logged but not created in Cognito).
 *
 * @param {Array} adOnlyUsers
 * @param {string[]} [allowedDomains] - Optional domain restriction list
 * @returns {Array}
 */
function processAdOnlyUsers(adOnlyUsers, allowedDomains) {
  const records = [];
  for (const adUser of adOnlyUsers) {
    // Domain Restriction check
    const domainCheck = validateEmailDomain(adUser.email, allowedDomains);
    if (!domainCheck.allowed) {
      logger.info("Sync", "AD_ONLY_DOMAIN_BLOCKED",
        `Skipping AD user (domain not permitted): ${adUser.email}`,
        { email: adUser.email, domain: domainCheck.domain }
      );
      continue;
    }

    logger.debug("Sync", "AD_ONLY", `Queuing for Cognito creation: ${adUser.email}`, { email: adUser.email });
    records.push({
      email: adUser.email,
      firstName: adUser.firstName,
      lastName: adUser.lastName,
      location: adUser.location,
      mobile: adUser.mobile || "",
      voice: adUser.voice || "",
      altEmail: adUser.altEmail || "",
      immutableId: adUser.immutableId,
      securityGroups: adUser.securityGroups || [],
      action: "create",
    });
  }
  return records;
}

// ─────────────────────────────────────────────────────────────────────────────
// STEP 5b: Users in both → Queue attribute updates (post-delta-filter)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * For users in both systems (already filtered by delta), determine what
 * needs updating in Cognito.
 *
 * AUTHORITATIVE SOURCES:
 *   • AD wins: firstName, lastName, location
 *   • Cognito wins: mobile, voice, altEmail
 *   • AD provides: immutableId (if missing in Cognito)
 *   • Groups: union (additive)
 *
 * Only generates a sync record if something actually needs to change.
 *
 * @param {Array} inBothPairs - Array of {ad, cognito} pairs (already delta-filtered)
 * @returns {Array} Cognito sync records for users needing updates
 */
function processUsersInBoth(inBothPairs) {
  const cognitoSyncRecords = [];
  const adUpdateRecords = [];

  for (const { ad: adUser, cognito: cognitoUser } of inBothPairs) {
    let needsCognitoUpdate = false;
    const cognitoChanges = []; // Track what changed for debug logging

    // Check immutableId
    if (!cognitoUser.immutableId && adUser.immutableId) {
      needsCognitoUpdate = true;
      cognitoChanges.push("immutableId (missing)");
    }

    // Check AD-authoritative fields (AD → Cognito)
    if (adUser.firstName && adUser.firstName !== cognitoUser.firstName) {
      needsCognitoUpdate = true;
      cognitoChanges.push(`firstName: "${cognitoUser.firstName}" → "${adUser.firstName}"`);
    }
    if (adUser.lastName && adUser.lastName !== cognitoUser.lastName) {
      needsCognitoUpdate = true;
      cognitoChanges.push(`lastName: "${cognitoUser.lastName}" → "${adUser.lastName}"`);
    }
    if (adUser.location && adUser.location !== cognitoUser.location) {
      needsCognitoUpdate = true;
      cognitoChanges.push(`location: "${cognitoUser.location}" → "${adUser.location}"`);
    }

    // Check security group differences (union)
    const adGroups = new Set(adUser.securityGroups || []);
    const cognitoGroups = new Set(cognitoUser.securityGroups || []);
    const mergedGroups = new Set([...adGroups, ...cognitoGroups]);

    if (mergedGroups.size > cognitoGroups.size) {
      needsCognitoUpdate = true;
      const newGroups = [...mergedGroups].filter((g) => !cognitoGroups.has(g));
      cognitoChanges.push(`groups: +${newGroups.join(", ")}`);
    }

    if (needsCognitoUpdate) {
      logger.debug("Sync", "USER_NEEDS_COGNITO_UPDATE", `${cognitoUser.email}: ${cognitoChanges.join("; ")}`, {
        email: cognitoUser.email, changes: cognitoChanges,
      });

      cognitoSyncRecords.push({
        email: cognitoUser.email,
        firstName: adUser.firstName || cognitoUser.firstName,
        lastName: adUser.lastName || cognitoUser.lastName,
        location: adUser.location || cognitoUser.location,
        mobile: cognitoUser.mobile || "",
        voice: cognitoUser.voice || "",
        altEmail: cognitoUser.altEmail || "",
        immutableId: adUser.immutableId || cognitoUser.immutableId,
        securityGroups: [...mergedGroups],
        action: "update",
      });
    }

    // Check Cognito-authoritative fields (Cognito → AD)
    const adChanges = {};
    const adChangeDescriptions = [];

    if (cognitoUser.mobile && cognitoUser.mobile !== adUser.mobile) {
      adChanges.mobile = cognitoUser.mobile;
      adChangeDescriptions.push(`mobile: "${adUser.mobile || ""}" → "${cognitoUser.mobile}"`);
    }
    if (cognitoUser.voice && cognitoUser.voice !== adUser.voice) {
      adChanges.voice = cognitoUser.voice;
      adChangeDescriptions.push(`voice: "${adUser.voice || ""}" → "${cognitoUser.voice}"`);
    }
    if (cognitoUser.altEmail && cognitoUser.altEmail !== adUser.altEmail) {
      adChanges.altEmail = cognitoUser.altEmail;
      adChangeDescriptions.push(`altEmail: "${adUser.altEmail || ""}" → "${cognitoUser.altEmail}"`);
    }

    if (Object.keys(adChanges).length > 0 && adUser.dn) {
      logger.debug("Sync", "USER_NEEDS_AD_UPDATE", `${cognitoUser.email}: ${adChangeDescriptions.join("; ")}`, {
        email: cognitoUser.email, changes: adChangeDescriptions,
      });
      adUpdateRecords.push({ dn: adUser.dn, email: cognitoUser.email, changes: adChanges });
    }

    if (!needsCognitoUpdate && Object.keys(adChanges).length === 0) {
      logger.debug("Sync", "USER_NO_CHANGES", `No changes needed: ${cognitoUser.email}`, {
        email: cognitoUser.email,
      });
    }
  }

  logger.info("Sync", "BOTH_RESULT",
    `${cognitoSyncRecords.length} Cognito updates, ${adUpdateRecords.length} AD updates from ${inBothPairs.length} shared users`,
    { cognitoUpdates: cognitoSyncRecords.length, adUpdates: adUpdateRecords.length, checked: inBothPairs.length }
  );

  return { cognitoSyncRecords, adUpdateRecords };
}

// ─────────────────────────────────────────────────────────────────────────────
// STEP 6: Sync Security Groups bidirectionally
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Ensure all security groups exist in both systems (additive only).
 *
 * @param {Set<string>} adGroupNames
 * @param {Set<string>} cognitoGroupNames
 * @returns {Promise<{createdInCognito: string[], createdInAD: string[]}>}
 */
async function syncSecurityGroups(adGroupNames, cognitoGroupNames) {
  const results = { createdInCognito: [], createdInAD: [] };

  for (const groupName of adGroupNames) {
    if (!cognitoGroupNames.has(groupName)) {
      try {
        await cognito.createGroup(groupName, `Synced from AD: ${groupName}`);
        results.createdInCognito.push(groupName);
      } catch (err) {
        logger.error("Sync", "GROUP_CREATE_COGNITO_FAILED",
          `Failed to create Cognito group: ${groupName}`,
          { groupName, error: err.message }
        );
      }
    }
  }

  for (const groupName of cognitoGroupNames) {
    if (!adGroupNames.has(groupName)) {
      try {
        await getProvider().createSecurityGroup(groupName);
        results.createdInAD.push(groupName);
      } catch (err) {
        logger.error("Sync", "GROUP_CREATE_AD_FAILED",
          `Failed to create AD group: ${groupName}`,
          { groupName, error: err.message }
        );
      }
    }
  }

  logger.info("Sync", "GROUPS_SYNCED",
    `Groups created: ${results.createdInCognito.length} in Cognito, ${results.createdInAD.length} in AD`,
    results
  );

  return results;
}

// ─────────────────────────────────────────────────────────────────────────────
// STEP 7: Execute Cognito batch write
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Execute the accumulated sync file — create new and update existing
 * users in a single pass.
 *
 * @param {Array} syncRecords
 * @returns {Promise<Object>}
 */
async function executeCognitoSync(syncRecords) {
  const creates = syncRecords.filter((r) => r.action === "create");
  const updates = syncRecords.filter((r) => r.action === "update");

  logger.info("Sync", "COGNITO_WRITE_START",
    `Cognito batch write: ${creates.length} creates, ${updates.length} updates`,
    { creates: creates.length, updates: updates.length }
  );

  const createResults = await cognito.batchCreateUsers(creates);
  const updateResults = await cognito.batchUpdateUserAttributes(updates);

  const result = {
    created: createResults.created.length,
    updated: updateResults.updated.length,
    createErrors: createResults.errors,
    updateErrors: updateResults.errors,
  };

  logger.info("Sync", "COGNITO_WRITE_DONE",
    `Cognito write complete: ${result.created} created, ${result.updated} updated, ` +
    `${result.createErrors.length + result.updateErrors.length} errors`,
    result
  );

  return result;
}

// ─────────────────────────────────────────────────────────────────────────────
// Main Batch Processor
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Process a single alphabetical batch.
 *
 * @param {string} startChar
 * @param {string} endChar
 * @param {string|null} lastSyncTimestamp - For delta filtering
 * @returns {Promise<Object>} Batch stats
 */
async function processBatch(startChar, endChar, lastSyncTimestamp) {
  const batchTimer = logger.startTimer("Sync", `Batch [${startChar}-${endChar}]`);

  const batchStats = {
    usersCreatedInCognito: 0,
    usersCreatedInAD: 0,
    usersUpdatedInCognito: 0,
    groupsCreatedInCognito: 0,
    groupsCreatedInAD: 0,
    usersSkippedByDelta: 0,
    errors: [],
  };

  // ───── STEP 1: Fetch Cognito users ────────────────────────────────────────
  logger.info("Sync", "STEP_1", "Fetching Cognito users...");
  const cognitoUsers = await cognito.fetchUsersByRange(startChar, endChar);

  // ───── STEP 2: Fetch LDAP directory users ──────────────────────────────────
  logger.info("Sync", "STEP_2", `Fetching ${getProvider().getProviderName()} users...`);
  const adUsers = await getProvider().fetchUsersByRange(startChar, endChar);

  // ───── STEP 3: Compare ────────────────────────────────────────────────────
  logger.info("Sync", "STEP_3", "Comparing user lists...");
  const diff = compareUsers(adUsers, cognitoUsers);

  // ───── DELTA FILTER: Skip unchanged shared users ──────────────────────────
  logger.info("Sync", "STEP_DELTA", "Applying delta sync filter to shared users...");
  const { changed: changedPairs, skipped: deltaSkipped } =
    filterUnchangedUsers(diff.inBoth, lastSyncTimestamp);
  batchStats.usersSkippedByDelta = deltaSkipped;

  // ───── STEP 4: Cognito-only → create in AD ───────────────────────────────
  logger.info("Sync", "STEP_4",
    `Processing ${diff.cognitoOnly.length} Cognito-only users → creating in AD`
  );
  const cognitoOnlySyncRecords = await processCognitoOnlyUsers(diff.cognitoOnly);
  batchStats.usersCreatedInAD += diff.cognitoOnly.length;

  // ───── STEP 5: AD-only → queue for Cognito ───────────────────────────────
  logger.info("Sync", "STEP_5",
    `Processing ${diff.adOnly.length} AD-only users → queuing for Cognito`
  );
  const adOnlySyncRecords = processAdOnlyUsers(diff.adOnly);

  // ───── STEP 5b: Shared users (delta-filtered) → queue updates ─────────────
  logger.info("Sync", "STEP_5B",
    `Checking ${changedPairs.length} changed shared users for attribute diffs`
  );
  const { cognitoSyncRecords: bothSyncRecords, adUpdateRecords } = processUsersInBoth(changedPairs);

  // ───── STEP 5c: Push Cognito-authoritative fields to AD ───────────────────
  for (const adUpdate of adUpdateRecords) {
    try {
      await getProvider().updateUser(adUpdate.dn, adUpdate.changes);
    } catch (err) {
      logger.error("Sync", "AD_UPDATE_FAILED", `Failed to update AD user: ${adUpdate.email}`, {
        email: adUpdate.email, dn: adUpdate.dn, error: err.message,
      });
      batchStats.errors.push({ email: adUpdate.email, error: `AD update: ${err.message}` });
    }
  }

  // ───── STEP 6: Sync security groups ───────────────────────────────────────
  logger.info("Sync", "STEP_6", "Syncing security groups...");
  const groupResults = await syncSecurityGroups(diff.allAdGroups, diff.allCognitoGroups);
  batchStats.groupsCreatedInCognito += groupResults.createdInCognito.length;
  batchStats.groupsCreatedInAD += groupResults.createdInAD.length;

  // ───── STEP 7: Single Cognito batch write ─────────────────────────────────
  const allSyncRecords = [
    ...cognitoOnlySyncRecords,
    ...adOnlySyncRecords,
    ...bothSyncRecords,
  ];

  logger.info("Sync", "STEP_7",
    `Executing Cognito batch write: ${allSyncRecords.length} total records`
  );
  const writeResults = await executeCognitoSync(allSyncRecords);

  batchStats.usersCreatedInCognito += writeResults.created;
  batchStats.usersUpdatedInCognito += writeResults.updated;
  batchStats.errors.push(...writeResults.createErrors, ...writeResults.updateErrors);

  // ───── Batch summary ──────────────────────────────────────────────────────
  batchTimer({
    ...batchStats,
    adUsers: adUsers.length,
    cognitoUsers: cognitoUsers.length,
  });

  logger.batchEnd(0, batchStats); // Index set by caller via logger.batchStart

  return batchStats;
}

// ─────────────────────────────────────────────────────────────────────────────
// Main Orchestrator
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Main sync orchestrator.
 *
 * Loads state and delta timestamp from S3, processes alphabetical batches
 * until done or Lambda time runs out, saves state, exits.
 *
 * @param {Object} [context] - Lambda context (getRemainingTimeInMillis)
 * @returns {Promise<Object>} Final sync state
 */
async function runSync(context) {
  const startTime = Date.now();

  const getTimeRemainingMs = () => {
    if (context && typeof context.getRemainingTimeInMillis === "function") {
      return context.getRemainingTimeInMillis();
    }
    return config.sync.maxLambdaMs - (Date.now() - startTime);
  };

  // Log startup configuration
  logger.logConfig();
  logger.info("Sync", "SYNC_STARTING", "AD ↔ Cognito two-way sync starting", {
    adUrl: config.ldap.url,
    ldapProvider: config.ldap.provider,
    cognitoPoolId: config.cognito.userPoolId,
    deltaEnabled: config.delta.enabled,
  });

  // ───── Load sync state ────────────────────────────────────────────────────
  let state = await loadState();

  if (!state || state.status === "complete") {
    state = createInitialState();
    logger.info("Sync", "NEW_RUN", `New sync run: ${state.syncId}`, { syncId: state.syncId });
  } else {
    logger.info("Sync", "RESUME_RUN",
      `Resuming sync: ${state.syncId} (batch ${state.currentBatch}/${state.totalBatches})`,
      { syncId: state.syncId, currentBatch: state.currentBatch }
    );
  }

  logger.setSyncId(state.syncId);

  // ───── Load delta timestamp for filtering ─────────────────────────────────
  const lastSyncTimestamp = await loadDeltaTimestamp();

  // ───── Process batches ────────────────────────────────────────────────────
  try {
    while (state.currentBatch < ALPHA_RANGES.length) {
      const remaining = getTimeRemainingMs();
      if (remaining < 120_000) {
        logger.info("Sync", "TIME_CHECKPOINT",
          `Time limit approaching (${Math.round(remaining / 1000)}s). Saving checkpoint...`,
          { remainingMs: remaining, currentBatch: state.currentBatch }
        );
        await saveState(state);
        return state;
      }

      const range = ALPHA_RANGES[state.currentBatch];
      logger.batchStart(state.currentBatch, state.totalBatches, range);

      // ───── STEP 8: Process this batch with delta filtering ────────────────
      const batchStats = await processBatch(range.start, range.end, lastSyncTimestamp);

      // Accumulate stats
      state.stats.usersCreatedInCognito += batchStats.usersCreatedInCognito;
      state.stats.usersCreatedInAD += batchStats.usersCreatedInAD;
      state.stats.usersUpdatedInCognito += batchStats.usersUpdatedInCognito;
      state.stats.groupsCreatedInCognito += batchStats.groupsCreatedInCognito;
      state.stats.groupsCreatedInAD += batchStats.groupsCreatedInAD;
      state.stats.usersSkippedByDelta += batchStats.usersSkippedByDelta;
      state.stats.errors.push(...batchStats.errors);

      state.currentBatch++;
      await saveState(state);
    }

    // ───── All batches complete ─────────────────────────────────────────────
    await markComplete(state);

    logger.summary("Sync", "SYNC COMPLETE — Final Statistics", {
      usersCreatedInCognito: state.stats.usersCreatedInCognito,
      usersUpdatedInCognito: state.stats.usersUpdatedInCognito,
      usersCreatedInAD: state.stats.usersCreatedInAD,
      groupsCreatedInCognito: state.stats.groupsCreatedInCognito,
      groupsCreatedInAD: state.stats.groupsCreatedInAD,
      usersSkippedByDelta: state.stats.usersSkippedByDelta,
      totalErrors: state.stats.errors.length,
      durationSeconds: Math.round((Date.now() - new Date(state.startedAt).getTime()) / 1000),
    });
  } catch (err) {
    logger.error("Sync", "FATAL_ERROR", `Sync failed: ${err.message}`, {
      error: err.message, stack: err.stack,
    });
    state.stats.errors.push({ fatal: true, error: err.message });
    await saveState(state);
    throw err;
  } finally {
    await getProvider().disconnect();
  }

  return state;
}

// ─────────────────────────────────────────────────────────────────────────────
// Multi-Tenant Entry Points
// ─────────────────────────────────────────────────────────────────────────────

const { createProvider } = require("./providers");
const { createCognitoUtils } = require("./cognito-utils");
const { createSyncState } = require("./sync-state");

/**
 * Run a full batch sync with injected per-tenant config.
 *
 * This is the multi-tenant equivalent of runSync(). It creates all
 * dependencies from the config object instead of using module singletons.
 *
 * @param {Object} cfg - Config object from buildConfig()
 * @param {Object} [context] - Lambda context (getRemainingTimeInMillis)
 * @returns {Promise<Object>} Final sync state
 */
async function runSyncWithConfig(cfg, context) {
  const startTime = Date.now();
  const provider = createProvider(cfg);
  const cognitoUtils = createCognitoUtils(cfg);
  const syncState = createSyncState(cfg);

  logger.setTenantId(cfg.tenantId);

  const getTimeRemainingMs = () => {
    if (context && typeof context.getRemainingTimeInMillis === "function") {
      return context.getRemainingTimeInMillis();
    }
    return cfg.sync.maxLambdaMs - (Date.now() - startTime);
  };

  logger.logConfig();
  logger.info("Sync", "SYNC_STARTING", "Multi-tenant AD ↔ Cognito sync starting", {
    tenantId: cfg.tenantId,
    adUrl: cfg.ldap.url,
    ldapProvider: cfg.ldap.provider,
    cognitoPoolId: cfg.cognito.userPoolId,
    deltaEnabled: cfg.delta.enabled,
  });

  let state = await syncState.loadState();
  if (!state || state.status === "complete") {
    state = syncState.createInitialState();
    state.tenantId = cfg.tenantId;
    logger.info("Sync", "NEW_RUN", `New sync run: ${state.syncId}`, { syncId: state.syncId, tenantId: cfg.tenantId });
  } else {
    logger.info("Sync", "RESUME_RUN",
      `Resuming sync: ${state.syncId} (batch ${state.currentBatch}/${state.totalBatches})`,
      { syncId: state.syncId, currentBatch: state.currentBatch, tenantId: cfg.tenantId }
    );
  }

  logger.setSyncId(state.syncId);

  const lastSyncTimestamp = await syncState.loadDeltaTimestamp();

  try {
    while (state.currentBatch < ALPHA_RANGES.length) {
      const remaining = getTimeRemainingMs();
      if (remaining < 120_000) {
        logger.info("Sync", "TIME_CHECKPOINT",
          `Time limit approaching (${Math.round(remaining / 1000)}s). Saving checkpoint...`,
          { remainingMs: remaining, currentBatch: state.currentBatch, tenantId: cfg.tenantId }
        );
        await syncState.saveState(state);
        return state;
      }

      const range = ALPHA_RANGES[state.currentBatch];
      logger.batchStart(state.currentBatch, state.totalBatches, range);

      const batchStats = await _processBatchWithDeps(
        range.start, range.end, lastSyncTimestamp, provider, cognitoUtils, cfg
      );

      state.stats.usersCreatedInCognito += batchStats.usersCreatedInCognito;
      state.stats.usersCreatedInAD += batchStats.usersCreatedInAD;
      state.stats.usersUpdatedInCognito += batchStats.usersUpdatedInCognito;
      state.stats.groupsCreatedInCognito += batchStats.groupsCreatedInCognito;
      state.stats.groupsCreatedInAD += batchStats.groupsCreatedInAD;
      state.stats.usersSkippedByDelta += batchStats.usersSkippedByDelta;
      state.stats.errors.push(...batchStats.errors);

      state.currentBatch++;
      await syncState.saveState(state);
    }

    await syncState.markComplete(state);

    logger.summary("Sync", "SYNC COMPLETE — Final Statistics", {
      tenantId: cfg.tenantId,
      usersCreatedInCognito: state.stats.usersCreatedInCognito,
      usersUpdatedInCognito: state.stats.usersUpdatedInCognito,
      usersCreatedInAD: state.stats.usersCreatedInAD,
      groupsCreatedInCognito: state.stats.groupsCreatedInCognito,
      groupsCreatedInAD: state.stats.groupsCreatedInAD,
      usersSkippedByDelta: state.stats.usersSkippedByDelta,
      totalErrors: state.stats.errors.length,
      durationSeconds: Math.round((Date.now() - new Date(state.startedAt).getTime()) / 1000),
    });
  } catch (err) {
    logger.error("Sync", "FATAL_ERROR", `Sync failed: ${err.message}`, {
      tenantId: cfg.tenantId, error: err.message, stack: err.stack,
    });
    state.stats.errors.push({ fatal: true, error: err.message });
    await syncState.saveState(state);
    throw err;
  } finally {
    await provider.disconnect();
    logger.setTenantId(null);
  }

  return state;
}

/**
 * Process a single batch using injected dependencies (for multi-tenant).
 * @private
 */
async function _processBatchWithDeps(startChar, endChar, lastSyncTimestamp, provider, cognitoUtils, cfg) {
  const batchTimer = logger.startTimer("Sync", `Batch [${startChar}-${endChar}]`);
  const batchStats = {
    usersCreatedInCognito: 0, usersCreatedInAD: 0, usersUpdatedInCognito: 0,
    groupsCreatedInCognito: 0, groupsCreatedInAD: 0, usersSkippedByDelta: 0, errors: [],
  };

  // ───── STEP 1: Fetch Cognito users ────────────────────────────────────────
  logger.info("Sync", "STEP_1", `[${startChar}-${endChar}] Fetching Cognito users...`, { tenantId: cfg.tenantId, range: `${startChar}-${endChar}` });
  const cognitoUsers = await cognitoUtils.fetchUsersByRange(startChar, endChar);
  logger.info("Sync", "STEP_1_RESULT", `[${startChar}-${endChar}] Cognito returned ${cognitoUsers.length} users`, {
    tenantId: cfg.tenantId, count: cognitoUsers.length, range: `${startChar}-${endChar}`,
    emails: cognitoUsers.map(u => u.email),
  });

  // ───── STEP 2: Fetch AD/LDAP users ────────────────────────────────────────
  logger.info("Sync", "STEP_2", `[${startChar}-${endChar}] Fetching ${provider.getProviderName()} users...`, { tenantId: cfg.tenantId, range: `${startChar}-${endChar}` });
  const adUsers = await provider.fetchUsersByRange(startChar, endChar);
  logger.info("Sync", "STEP_2_RESULT", `[${startChar}-${endChar}] AD returned ${adUsers.length} users`, {
    tenantId: cfg.tenantId, count: adUsers.length, range: `${startChar}-${endChar}`,
    emails: adUsers.map(u => u.email),
  });

  // ───── STEP 3: Compare ────────────────────────────────────────────────────
  logger.info("Sync", "STEP_3", `[${startChar}-${endChar}] Comparing user lists...`, { tenantId: cfg.tenantId });
  const diff = compareUsers(adUsers, cognitoUsers);
  logger.info("Sync", "STEP_3_RESULT", `[${startChar}-${endChar}] Diff: ${diff.adOnly.length} AD-only, ${diff.cognitoOnly.length} Cognito-only, ${diff.inBoth.length} in both`, {
    tenantId: cfg.tenantId, adOnly: diff.adOnly.length, cognitoOnly: diff.cognitoOnly.length, inBoth: diff.inBoth.length,
    adOnlyEmails: diff.adOnly.map(u => u.email),
    cognitoOnlyEmails: diff.cognitoOnly.map(u => u.email),
    adGroups: [...diff.allAdGroups],
    cognitoGroups: [...diff.allCognitoGroups],
  });

  // ───── STEP DELTA: Filter unchanged shared users ──────────────────────────
  const deltaEnabled = cfg.delta.enabled;
  logger.info("Sync", "STEP_DELTA", `[${startChar}-${endChar}] Applying delta filter (enabled=${deltaEnabled})...`, { tenantId: cfg.tenantId, deltaEnabled, lastSyncTimestamp });
  const { changed: changedPairs, skipped: deltaSkipped } =
    _filterUnchangedWithConfig(diff.inBoth, lastSyncTimestamp, deltaEnabled);
  batchStats.usersSkippedByDelta = deltaSkipped;
  logger.info("Sync", "STEP_DELTA_RESULT", `[${startChar}-${endChar}] Delta: ${changedPairs.length} to process, ${deltaSkipped} skipped`, {
    tenantId: cfg.tenantId, changed: changedPairs.length, skipped: deltaSkipped,
  });

  // ───── STEP 4: Cognito-only → create in AD ───────────────────────────────
  logger.info("Sync", "STEP_4", `[${startChar}-${endChar}] Processing ${diff.cognitoOnly.length} Cognito-only users → creating in AD`, { tenantId: cfg.tenantId, count: diff.cognitoOnly.length });
  const cognitoOnlySyncRecords = [];
  for (const user of diff.cognitoOnly) {
    try {
      logger.debug("Sync", "COGNITO_ONLY", `Creating in LDAP: ${user.email}`, { email: user.email, tenantId: cfg.tenantId });
      let adUser;
      try {
        adUser = await provider.createUser({
          email: user.email, firstName: user.firstName, lastName: user.lastName,
          location: user.location, mobile: user.mobile, voice: user.voice,
        });
      } catch (createErr) {
        // Handle "Entry Already Exists" (error 68) — user was created by a previous sync
        // attempt but AD search can't find them (permissions issue). Read back instead.
        if (createErr.code === 68 || (createErr.message && (createErr.message.includes("Entry Already Exists") || createErr.message.includes("error code 68")))) {
          logger.info("Sync", "COGNITO_ONLY_EXISTS",
            `User ${user.email} already exists in AD — reading back for immutableId`,
            { email: user.email, tenantId: cfg.tenantId });
          adUser = await provider.readUserByEmail(user.email);
          if (!adUser) {
            // Can't read back either — likely AD search permission issue. Skip silently.
            logger.info("Sync", "COGNITO_ONLY_SKIP",
              `User ${user.email} exists in AD but cannot be read back (permission issue) — skipping`,
              { email: user.email, tenantId: cfg.tenantId });
            continue;
          }
        } else {
          throw createErr; // Re-throw non-68 errors
        }
      }
      if (adUser) {
        cognitoOnlySyncRecords.push({
          email: user.email, firstName: user.firstName, lastName: user.lastName,
          location: user.location, mobile: user.mobile, voice: user.voice,
          altEmail: user.altEmail, immutableId: adUser.immutableId,
          securityGroups: user.securityGroups || [], action: "update",
        });
        batchStats.usersCreatedInAD++;

        // Add user to AD security groups
        for (const groupName of user.securityGroups || []) {
          try {
            const adGroups = await provider.fetchSecurityGroups();
            const group = adGroups.find((g) => g.name === groupName);
            if (group && adUser.dn) {
              await provider.addUserToGroup(adUser.dn, group.dn);
            }
          } catch (groupErr) {
            logger.error("Sync", "AD_GROUP_ADD_WARN",
              `Could not add ${user.email} to AD group ${groupName}`,
              { email: user.email, group: groupName, error: groupErr.message });
          }
        }
      }
    } catch (err) {
      logger.error("Sync", "COGNITO_ONLY_FAILED", `Error: ${user.email}: ${err.message}`, { email: user.email, error: err.message });
      batchStats.errors.push({ email: user.email, error: err.message });
    }
  }

  // ───── STEP 5: AD-only → create in Cognito ───────────────────────────────
  // Domain Restriction: cfg.allowedDomains is loaded from amfaConfigs by the worker Lambda
  logger.info("Sync", "STEP_5", `[${startChar}-${endChar}] Processing ${diff.adOnly.length} AD-only users → queuing for Cognito creation`, {
    tenantId: cfg.tenantId, count: diff.adOnly.length,
    emails: diff.adOnly.map(u => u.email),
    allowedDomains: cfg.allowedDomains || null,
  });
  const adOnlySyncRecords = processAdOnlyUsers(diff.adOnly, cfg.allowedDomains);

  // ───── STEP 5b: Shared users (delta-filtered) → queue updates ─────────────
  logger.info("Sync", "STEP_5B", `[${startChar}-${endChar}] Checking ${changedPairs.length} changed shared users for attribute diffs`, { tenantId: cfg.tenantId, count: changedPairs.length });
  const { cognitoSyncRecords: bothSyncRecords, adUpdateRecords: mtAdUpdateRecords } = processUsersInBoth(changedPairs);

  // ───── STEP 5c: Push Cognito-authoritative fields to AD ───────────────────
  if (mtAdUpdateRecords.length > 0) {
    logger.info("Sync", "STEP_5C", `[${startChar}-${endChar}] Pushing ${mtAdUpdateRecords.length} Cognito→AD attribute updates`, { tenantId: cfg.tenantId, count: mtAdUpdateRecords.length });
    for (const adUpdate of mtAdUpdateRecords) {
      try {
        await provider.updateUser(adUpdate.dn, adUpdate.changes);
      } catch (err) {
        logger.error("Sync", "AD_UPDATE_FAILED", `Failed to update AD user: ${adUpdate.email}`, {
          email: adUpdate.email, dn: adUpdate.dn, error: err.message, tenantId: cfg.tenantId,
        });
        batchStats.errors.push({ email: adUpdate.email, error: `AD update: ${err.message}` });
      }
    }
  }

  // ───── STEP 6: Sync security groups ───────────────────────────────────────
  logger.info("Sync", "STEP_6", `[${startChar}-${endChar}] Syncing security groups (AD: ${diff.allAdGroups.size}, Cognito: ${diff.allCognitoGroups.size})`, {
    tenantId: cfg.tenantId, adGroupCount: diff.allAdGroups.size, cognitoGroupCount: diff.allCognitoGroups.size,
    adGroups: [...diff.allAdGroups], cognitoGroups: [...diff.allCognitoGroups],
  });
  for (const groupName of diff.allAdGroups) {
    if (!diff.allCognitoGroups.has(groupName)) {
      try { await cognitoUtils.createGroup(groupName, `Synced from AD: ${groupName}`); batchStats.groupsCreatedInCognito++; }
      catch (err) { logger.error("Sync", "GROUP_CREATE_COGNITO_FAILED", `Failed: ${groupName}`, { groupName, error: err.message }); }
    }
  }
  for (const groupName of diff.allCognitoGroups) {
    if (!diff.allAdGroups.has(groupName)) {
      try {
        const result = await provider.createSecurityGroup(groupName);
        if (result.created) batchStats.groupsCreatedInAD++;
      } catch (err) { logger.error("Sync", "GROUP_CREATE_AD_FAILED", `Failed: ${groupName}`, { groupName, error: err.message }); }
    }
  }

  // ───── STEP 7: Cognito batch write ─────────────────────────────────────────
  const allSyncRecords = [...cognitoOnlySyncRecords, ...adOnlySyncRecords, ...bothSyncRecords];
  const creates = allSyncRecords.filter((r) => r.action === "create");
  const updates = allSyncRecords.filter((r) => r.action === "update");
  logger.info("Sync", "STEP_7", `[${startChar}-${endChar}] Executing Cognito batch write: ${creates.length} creates, ${updates.length} updates (${allSyncRecords.length} total)`, {
    tenantId: cfg.tenantId, creates: creates.length, updates: updates.length, total: allSyncRecords.length,
    createEmails: creates.map(r => r.email),
    updateEmails: updates.map(r => r.email),
  });
  const createResults = await cognitoUtils.batchCreateUsers(creates);
  const updateResults = await cognitoUtils.batchUpdateUserAttributes(updates);

  batchStats.usersCreatedInCognito += createResults.created.length;
  batchStats.usersUpdatedInCognito += updateResults.updated.length;
  batchStats.errors.push(...createResults.errors, ...updateResults.errors);

  batchTimer({ ...batchStats, adUsers: adUsers.length, cognitoUsers: cognitoUsers.length });
  return batchStats;
}

/**
 * Delta filter using explicit config flag (for multi-tenant).
 * @private
 */
function _filterUnchangedWithConfig(inBothPairs, lastSyncTimestamp, deltaEnabled) {
  if (!lastSyncTimestamp || !deltaEnabled) {
    return { changed: inBothPairs, skipped: 0 };
  }
  const cutoff = new Date(lastSyncTimestamp);
  const changed = [];
  let skipped = 0;
  for (const pair of inBothPairs) {
    const adChanged = pair.ad.whenChanged ? new Date(pair.ad.whenChanged) : null;
    const cognitoChanged = pair.cognito.lastModified ? new Date(pair.cognito.lastModified) : null;
    if (adChanged && cognitoChanged && adChanged < cutoff && cognitoChanged < cutoff) {
      skipped++;
    } else {
      changed.push(pair);
    }
  }
  logger.info("Delta", "FILTER_RESULT", `Delta filter: ${skipped} skipped, ${changed.length} to process`, { total: inBothPairs.length, changed: changed.length, skipped });
  return { changed, skipped };
}

/**
 * Sync a single user between AD and Cognito (event-driven mode).
 *
 * Called when a user's attributes change in Cognito (admin update, password
 * reset, MFA change). Loads the user from both systems, applies the
 * "fill empty" merge, and writes changes to both sides.
 *
 * @param {Object} cfg - Config object from buildConfig()
 * @param {string} username - Cognito username (typically email)
 * @returns {Promise<Object>} Sync result
 */
async function syncSingleUser(cfg, username) {
  const provider = createProvider(cfg);
  const cognitoUtils = createCognitoUtils(cfg);

  logger.setTenantId(cfg.tenantId);
  logger.info("Sync", "SINGLE_USER_START", `Single-user sync: ${username}`, {
    tenantId: cfg.tenantId, username, cognitoPoolId: cfg.cognito.userPoolId,
  });

  try {
    // Fetch single user from Cognito via AdminGetUser (O(1) lookup)
    let cognitoUser;
    try {
      cognitoUser = await cognitoUtils.adminGetUser(username);
    } catch (err) {
      if (err.name === "UserNotFoundException") {
        logger.info("Sync", "SINGLE_USER_NOT_FOUND", `User not found in Cognito: ${username}`, { username, tenantId: cfg.tenantId });
        return { status: "skipped", reason: "user_not_found_in_cognito" };
      }
      throw err;
    }

    // Fetch from AD
    let adUser = await provider.readUserByEmail(cognitoUser.email);

    if (!adUser) {
      // User exists in Cognito but not AD → create in AD
      logger.info("Sync", "SINGLE_USER_CREATE_AD", `Creating in AD: ${cognitoUser.email}`, { email: cognitoUser.email, tenantId: cfg.tenantId });
      try {
        const createdAdUser = await provider.createUser({
          email: cognitoUser.email, firstName: cognitoUser.firstName,
          lastName: cognitoUser.lastName, location: cognitoUser.location,
          mobile: cognitoUser.mobile, voice: cognitoUser.voice,
        });
        if (createdAdUser && createdAdUser.immutableId) {
          await cognitoUtils.updateUserAttributes({ email: cognitoUser.email, immutableId: createdAdUser.immutableId });
        }
        return { status: "created_in_ad", email: cognitoUser.email };
      } catch (createErr) {
        // Handle "Entry Already Exists" (error 68) — user exists in AD but readUserByEmail
        // couldn't find them (search permission or attribute mismatch). Read back and continue
        // with the merge/update flow instead of failing.
        if (createErr.code === 68 || (createErr.message && (createErr.message.includes("Entry Already Exists") || createErr.message.includes("error code 68")))) {
          logger.info("Sync", "SINGLE_USER_EXISTS_IN_AD",
            `User ${cognitoUser.email} already exists in AD (search missed) — retrying read for merge flow`,
            { email: cognitoUser.email, tenantId: cfg.tenantId });
          const retryRead = await provider.readUserByEmail(cognitoUser.email);
          if (retryRead) {
            adUser = retryRead; // Fall through to merge/update logic below
          } else {
            logger.warn("Sync", "SINGLE_USER_RETRY_READ_FAILED",
              `User ${cognitoUser.email} exists in AD but cannot be read back — skipping`,
              { email: cognitoUser.email, tenantId: cfg.tenantId });
            return { status: "skipped", reason: "ad_exists_but_unreadable", email: cognitoUser.email };
          }
        } else {
          throw createErr; // Re-throw non-68 errors
        }
      }
    }

    // User exists in both → apply "fill empty" merge
    const cognitoUpdates = {};
    const adUpdates = {};
    const fieldMappings = cfg.fieldMappings || {};

    // For each mapped field, apply merge logic
    const mergeField = (cognitoAttr, cognitoValue, adValue, direction) => {
      if (direction === "none") return;
      if (direction === "cognito_source") {
        if (cognitoValue) { adUpdates[cognitoAttr] = cognitoValue; }
        else if (adValue && !cognitoValue) { cognitoUpdates[cognitoAttr] = adValue; }
      } else if (direction === "ad_source") {
        if (adValue) { cognitoUpdates[cognitoAttr] = adValue; }
        else if (cognitoValue && !adValue) { adUpdates[cognitoAttr] = cognitoValue; }
      }
    };

    // Apply merge for standard fields
    mergeField("firstName", cognitoUser.firstName, adUser.firstName,
      (fieldMappings["given_name"] || {}).syncDirection || "cognito_source");
    mergeField("lastName", cognitoUser.lastName, adUser.lastName,
      (fieldMappings["family_name"] || {}).syncDirection || "cognito_source");
    mergeField("location", cognitoUser.location, adUser.location,
      (fieldMappings["locale"] || {}).syncDirection || "cognito_source");
    mergeField("mobile", cognitoUser.mobile, adUser.mobile,
      (fieldMappings["phone_number"] || {}).syncDirection || "cognito_source");
    mergeField("voice", cognitoUser.voice, adUser.voice,
      (fieldMappings["custom:voice-number"] || {}).syncDirection || "cognito_source");
    mergeField("altEmail", cognitoUser.altEmail, adUser.altEmail,
      (fieldMappings["custom:alter-email"] || {}).syncDirection || "cognito_source");

    // immutableId: always from AD
    if (adUser.immutableId && !cognitoUser.immutableId) {
      cognitoUpdates.immutableId = adUser.immutableId;
    }

    // Update Cognito if needed
    const hasCognitoChanges = Object.keys(cognitoUpdates).length > 0;
    if (hasCognitoChanges) {
      logger.info("Sync", "SINGLE_USER_UPDATE_COGNITO", `Updating Cognito: ${cognitoUser.email}`, {
        email: cognitoUser.email, updates: cognitoUpdates, tenantId: cfg.tenantId,
      });
      await cognitoUtils.updateUserAttributes({
        email: cognitoUser.email, ...cognitoUpdates,
      });
    }

    // Update AD if needed (Cognito-authoritative fields → AD)
    const hasAdChanges = Object.keys(adUpdates).length > 0;
    if (hasAdChanges && adUser.dn) {
      try {
        logger.info("Sync", "SINGLE_USER_UPDATE_AD", `Updating AD: ${cognitoUser.email}`, {
          email: cognitoUser.email, updates: adUpdates, dn: adUser.dn, tenantId: cfg.tenantId,
        });
        await provider.updateUser(adUser.dn, adUpdates);
        logger.info("Sync", "SINGLE_USER_AD_UPDATED", `AD updated: ${cognitoUser.email}`, {
          email: cognitoUser.email, tenantId: cfg.tenantId,
        });
      } catch (adErr) {
        // Non-fatal — log error but continue with group sync
        logger.error("Sync", "SINGLE_USER_AD_UPDATE_FAILED",
          `Failed to update AD for ${cognitoUser.email}: ${adErr.message}`,
          { email: cognitoUser.email, dn: adUser.dn, error: adErr.message, tenantId: cfg.tenantId }
        );
      }
    }

    // Sync groups (additive)
    const adGroups = new Set(adUser.securityGroups || []);
    const cognitoGroups = new Set(cognitoUser.securityGroups || []);
    for (const group of adGroups) {
      if (!cognitoGroups.has(group)) {
        await cognitoUtils.addUserToGroup(cognitoUser.email, group);
      }
    }
    for (const group of cognitoGroups) {
      if (!adGroups.has(group)) {
        try {
          const adGroupList = await provider.fetchSecurityGroups();
          let targetGroup = adGroupList.find((g) => g.name === group);
          if (!targetGroup) {
            const dn = await provider.createSecurityGroup(group);
            targetGroup = { name: group, dn };
          }
          if (adUser.dn && targetGroup.dn) {
            await provider.addUserToGroup(adUser.dn, targetGroup.dn);
          }
        } catch (err) {
          logger.error("Sync", "SINGLE_USER_GROUP_FAILED", `Group sync failed: ${group}`, { group, error: err.message });
        }
      }
    }

    logger.info("Sync", "SINGLE_USER_COMPLETE", `Single-user sync complete: ${cognitoUser.email}`, {
      email: cognitoUser.email, tenantId: cfg.tenantId,
      cognitoUpdated: hasCognitoChanges,
    });

    return { status: "synced", email: cognitoUser.email, cognitoUpdated: hasCognitoChanges };
  } catch (err) {
    logger.error("Sync", "SINGLE_USER_FAILED", `Single-user sync failed: ${username}: ${err.message}`, {
      username, tenantId: cfg.tenantId, error: err.message, stack: err.stack,
    });
    throw err;
  } finally {
    await provider.disconnect();
    logger.setTenantId(null);
  }
}

module.exports = {
  runSync,
  runSyncWithConfig,
  syncSingleUser,
  processBatch,
  compareUsers,
  filterUnchangedUsers,
  processCognitoOnlyUsers,
  processAdOnlyUsers,
  processUsersInBoth,
  syncSecurityGroups,
  executeCognitoSync,
};
